    'КонецПроцедуры',
    '',
    '&НаСервере',
    'Функция СобратьТекстОшибки1С(БазовыйТекстОшибки)',
    '\tИтогОшибки = СокрЛП(Строка(БазовыйТекстОшибки));',
    '\tДеталиСообщений = "";',
