    '',
    '&НаСервере',
    'Функция РазрешитьИмяДокументаБП30(ВидМетаИсходный)',
    '\tЧистыйВид = СокрЛП(Строка(ВидМетаИсходный));',
    '\tЕсли ЧистыйВид = "ПоступлениеНаличных" Или ЧистыйВид = "ПриходныйКассовыйОрдер" Тогда',
    '\t\tЕсли Метаданные.Документы.Найти("ПриходныйКассовыйОрдер") <> Неопределено Тогда',
