    '\t\tИначеЕсли Метаданные.Документы.Найти("ПоступлениеНаличных") <> Неопределено Тогда',
    '\t\t\tВозврат "ПоступлениеНаличных";',
    '\t\tКонецЕсли;',
    '\t\tВозврат "ПриходныйКассовыйОрдер";',
    '\tИначеЕсли ЧистыйВид = "ВыдачаНаличных" Или ЧистыйВид = "РасходныйКассовыйОрдер" Тогда',
    '\t\tЕсли Метаданные.Документы.Найти("РасходныйКассовыйОрдер") <> Неопределено Тогда',
    '\t\t\tВозврат "РасходныйКассовыйОрдер";',
    '\t\tИначеЕсли Метаданные.Документы.Найти("ВыдачаНаличных") <> Неопределено Тогда',
    '\t\t\tВозврат "ВыдачаНаличных";',
    '\t\tКонецЕсли;',
    '\t\tВозврат "РасходныйКассовыйОрдер";',
    '\tИначеЕсли ЧистыйВид = "Увольнение" Или ЧистыйВид = "УвольнениеИзОрганизации" Тогда',
    '\t\tЕсли Метаданные.Документы.Найти("Увольнение") <> Неопределено Тогда',
    '\t\t\tВозврат "Увольнение";',
    '\t\tИначеЕсли Метаданные.Документы.Найти("УвольнениеИзОрганизации") <> Неопределено Тогда',
    '\t\t\tВозврат "УвольнениеИзОрганизации";',
    '\t\tКонецЕсли;',
    '\t\tВозврат "Увольнение";',
    '\tИначеЕсли ЧистыйВид = "ТребованиеНакладная" Или ЧистыйВид = "РасходМатериалов" Тогда',
