    'КонецПроцедуры',
    '',
    '&НаСервере',
    'Функция ЗаменитьПодстрокуБП(ИсхСтрока, ИскомаяПодстрока, ПодстрокаЗамены)',
    '\tИскСтр = Строка(ИскомаяПодстрока);',
