    'КонецФункции',
    '',
    '&НаСервере',
    'Функция УсловиеБезГруппСправочника(ИмяСправочника, ПсевдонимТаблицы)',
    '\tПопытка',
    '\t\tМДСпрГр = Метаданные.Справочники.Найти(ИмяСправочника);',
    '\t\tЕсли МДСпрГр <> Неопределено И МДСпрГр.Иерархический Тогда',
    '\t\t\tЕстьГруппыСпр = Истина;',
    '\t\t\tПопытка',
    '\t\t\t\tЕстьГруппыСпр = (МДСпрГр.ВидИерархии = Метаданные.СвойстваОбъектов.ВидИерархии.ИерархияГруппИЭлементов);',
    '\t\t\tИсключение',
    '\t\t\t\tЕстьГруппыСпр = (Найти(ВРег(Строка(МДСпрГр.ВидИерархии)), "ГРУПП") > 0);',
    '\t\t\tКонецПопытки;',
    '\t\t\tЕсли ЕстьГруппыСпр Тогда',
    '\t\t\t\tВозврат " И НЕ " + ПсевдонимТаблицы + ".ЭтоГруппа";',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\tВозврат "";',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция НайтиВидОперацииПоМетаданным(Док, КандидатыИменИСинонимов)',
    '\tЕсли Док = Неопределено Или КандидатыИменИСинонимов = Неопределено Тогда',
    '\t\tВозврат Неопределено;',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tРеквВО = Док.Метаданные().Реквизиты.Найти("ВидОперации");',
    '\t\tЕсли РеквВО = Неопределено Тогда',
    '\t\t\tВозврат Неопределено;',
    '\t\tКонецЕсли;',
    '\t\tТипВО = Док.Метаданные().Реквизиты.ВидОперации.Тип.Типы()[0];',
    '\t\tМДПер = Метаданные.НайтиПоТипу(ТипВО);',
    '\t\tЕсли МДПер = Неопределено Тогда',
    '\t\t\tВозврат Неопределено;',
    '\t\tКонецЕсли;',
    '\t\tМенеджерПер = Перечисления[МДПер.Имя];',
    '\t\tСчетчикКанд = 0;',
    '\t\tДля Каждого КандЭл Из КандидатыИменИСинонимов Цикл',
    '\t\t\tСчетчикКанд = СчетчикКанд + 1;',
    '\t\t\tЕсли СчетчикКанд > 100 Тогда',
    '\t\t\t\tПрервать;',
    '\t\t\tКонецЕсли;',
    '\t\t\tКандВРег = СокрЛП(ВРег(Строка(КандЭл)));',
    '\t\t\tЕсли ПустаяСтрока(КандВРег) Тогда',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '\t\t\tСчетчикЗн = 0;',
    '\t\t\tДля Каждого Зн Из МДПер.ЗначенияПеречисления Цикл',
    '\t\t\t\tСчетчикЗн = СчетчикЗн + 1;',
    '\t\t\t\tЕсли СчетчикЗн > 500 Тогда',
    '\t\t\t\t\tПрервать;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tЕсли СокрЛП(ВРег(Зн.Имя)) = КандВРег Или СокрЛП(ВРег(Зн.Синоним)) = КандВРег Тогда',
    '\t\t\t\t\tВозврат МенеджерПер[Зн.Имя];',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЦикла;',
    '\t\tКонецЦикла;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\tВозврат Неопределено;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция ПолучитьКандидатыВидаОперации(КаноническийВид)',
    '\tКанд = Новый Массив;',
