    '\t\tКанд.Добавить("ПрочийРасход");',
    '\t\tКанд.Добавить("Прочий расход");',
    '\tИначеЕсли КаноническийВид = "ПрочийПриход" Тогда',
    '\t\tКанд.Добавить("ПрочийПриход");',
    '\t\tКанд.Добавить("Прочий приход");',
    '\tИначеЕсли КаноническийВид = "ВозвратПокупателю" Тогда',
    '\t\tКанд.Добавить("ВозвратПокупателю");',
    '\t\tКанд.Добавить("Возврат покупателю");',
    '\t\tКанд.Добавить("ВозвратДенежныхСредствПокупателю");',
    '\t\tКанд.Добавить("Возврат денежных средств покупателю");',
    '\tИначеЕсли КаноническийВид = "ВозвратОтПоставщика" Тогда',
    '\t\tКанд.Добавить("ВозвратОтПоставщика");',
