    '\t\tКанд.Добавить("Перечисление налога");',
    '\tИначеЕсли КаноническийВид = "РасчетыПоКредитамИЗаймам" Или КаноническийВид = "РасчетыПоКредитамИЗаймамПоступление" Тогда',
    '\t\tКанд.Добавить("РасчетыПоКредитамИЗаймам");',
    '\t\tКанд.Добавить("Расчеты по кредитам и займам");',
    '\t\tКанд.Добавить("ПолучениеКредитаВБанке");',
    '\t\tКанд.Добавить("Получение кредита в банке");',
    '\t\tКанд.Добавить("ПолучениеЗаймаОтКонтрагента");',
    '\t\tКанд.Добавить("Получение займа от контрагента");',
    '\tИначеЕсли КаноническийВид = "РасчетыПоКредитамИЗаймамСписание" Тогда',
    '\t\tКанд.Добавить("РасчетыПоКредитамИЗаймам");',
    '\t\tКанд.Добавить("Расчеты по кредитам и займам");',
    '\t\tКанд.Добавить("ПогашениеКредитаБанку");',
    '\t\tКанд.Добавить("Погашение кредита банку");',
