    'Функция НайтиСчет(КодСчета)',
    '\tЧистыйКод = СокрЛП(Строка(КодСчета));',
    '\tЕсли ПустаяСтрока(ЧистыйКод) Тогда',
    '\t\tВозврат ПланыСчетов.Хозрасчетный.ПустаяСсылка();',
    '\tКонецЕсли;',
    '\tНайденный = ПланыСчетов.Хозрасчетный.НайтиПоКоду(ЧистыйКод);',
    '\tЕсли ЗначениеЗаполнено(Найденный) Тогда',
    '\t\tВозврат Найденный;',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tЗапросСчКод = Новый Запрос;',
    '\t\tЗапросСчКод.Текст = "ВЫБРАТЬ ПЕРВЫЕ 5 Сч.Ссылка КАК Ссылка, Сч.Код КАК Код ИЗ ПланСчетов.Хозрасчетный КАК Сч ГДЕ НЕ Сч.ПометкаУдаления И Сч.Код ПОДОБНО &ШаблКода";',
    '\t\tЗапросСчКод.УстановитьПараметр("ШаблКода", ЧистыйКод + "%");',
    '\t\tТабСчКод = ЗапросСчКод.Выполнить().Выгрузить();',
    '\t\tСчИтерКод = 0;',
    '\t\tДля Каждого СтрСчКод Из ТабСчКод Цикл',
    '\t\t\tСчИтерКод = СчИтерКод + 1;',
    '\t\t\tЕсли СчИтерКод > 20 Тогда Прервать; КонецЕсли;',
    '\t\t\tЕсли СокрЛП(Строка(СтрСчКод.Код)) = ЧистыйКод Тогда',
    '\t\t\t\tВозврат СтрСчКод.Ссылка;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЦикла;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\tВозврат Найденный;',
    'КонецФункции',
