    '&НаСервере',
    'Функция НайтиСчетСДефолтом(КодСчета, КодДефолта = "76.09")',
    '\tЧистыйКод = СокрЛП(Строка(КодСчета));',
    '\tЕсли НЕ ПустаяСтрока(ЧистыйКод) Тогда',
