    '&НаСервере',
    'Функция ИзвлечьКоррСчетБанкаКассыИзJSON(ДокДанные, ЭтоПриходДенег, ПрефиксДенежногоСчета)',
    '\tРез = Новый Структура("КодСчета, СубконтоТекст", "", "");',
    '\tШапкаЛок = ПолучитьИзСоответствия(ДокДанные, "header", Новый Соответствие);',
