    '\tДлинаПреф = СтрДлина(ПрефиксДенежногоСчета);',
    '\tДля Каждого ПрЛок Из ПроводкиЛок Цикл',
    '\t\tДтЛок = СокрЛП(Строка(ПолучитьИзСоответствия(ПрЛок, "debit", "")));',
    '\t\tКтЛок = СокрЛП(Строка(ПолучитьИзСоответствия(ПрЛок, "credit", "")));',
    '\t\tЕсли ЭтоПриходДенег Тогда',
    '\t\t\tЕсли Лев(ДтЛок, ДлинаПреф) = ПрефиксДенежногоСчета И НЕ ПустаяСтрока(КтЛок) Тогда',
    '\t\t\t\tРез.КодСчета = КтЛок;',
    '\t\t\t\tРез.СубконтоТекст = СокрЛП(Строка(ПолучитьИзСоответствия(ПрЛок, "creditSubconto", "")));',
