    '\t\t\tКонецЕсли;',
    '\t\tИначе',
    '\t\t\tЕсли Лев(КтЛок, ДлинаПреф) = ПрефиксДенежногоСчета И НЕ ПустаяСтрока(ДтЛок) Тогда',
    '\t\t\t\tРез.КодСчета = ДтЛок;',
    '\t\t\t\tРез.СубконтоТекст = СокрЛП(Строка(ПолучитьИзСоответствия(ПрЛок, "debitSubconto", "")));',
    '\t\t\t\tВозврат Рез;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
