    '\t\t\tРез.КодСчета = СокрЛП(Строка(ПолучитьИзСоответствия(ПервПр, "debit", "")));',
    '\t\t\tРез.СубконтоТекст = СокрЛП(Строка(ПолучитьИзСоответствия(ПервПр, "debitSubconto", "")));',
    '\t\tКонецЕсли;',
    '\tКонецЕсли;',
    '\tЕсли ПустаяСтрока(Рез.КодСчета) Тогда',
    '\t\tЕсли ЭтоПриходДенег Тогда',
    '\t\t\tРез.КодСчета = СокрЛП(Строка(ПолучитьИзСоответствия(ШапкаЛок, "creditAccount", "")));',
    '\t\tИначе',
    '\t\t\tРез.КодСчета = СокрЛП(Строка(ПолучитьИзСоответствия(ШапкаЛок, "debitAccount", "")));',
