    '&НаСервере',
    'Процедура УстановитьСчетУчетаДенежныхСредствПоМетаданным(ДокОбъект, СчетДССсылка)',
    '\tЕсли ДокОбъект = Неопределено Или НЕ ЗначениеЗаполнено(СчетДССсылка) Тогда',
