    '\tИсклДС.Добавить("СЧЕТДЕБЕТА");',
    '\tИсклДС.Добавить("ДЕБЕТ");',
    '\tИсклДС.Добавить("СЧЕТКРЕДИТА");',
    '\tИсклДС.Добавить("КРЕДИТ");',
    '\tИсклДС.Добавить("КОРРЕСПОНД");',
    '\tИсклДС.Добавить("ЗАТРАТ");',
    '\tИсклДС.Добавить("НДС");',
    '\tИсклДС.Добавить("КОМИСС");',
    '\tИсклДС.Добавить("ДОХОД");',
    '\tИсклДС.Добавить("РАСХОД");',
