    '\t\tПопытка',
    '\t\t\tТЧРасшК = ДокОбъект.Метаданные().ТабличныеЧасти.Найти("РасшифровкаПлатежа");',
    '\t\t\tЕсли ТЧРасшК <> Неопределено Тогда',
    '\t\t\t\tИмяКоррТЧ = НайтиИмяРеквизитаСчетаПоМетаданным(ТЧРасшК.Реквизиты, КлКорр, ИсклКоррШапка);',
    '\t\t\t\tДокОбъект.РасшифровкаПлатежа.Очистить();',
    '\t\t\t\tЕсли НЕ ПустаяСтрока(ИмяКоррТЧ) Тогда',
    '\t\t\t\t\tСтрКоррК = ДокОбъект.РасшифровкаПлатежа.Добавить();',
    '\t\t\t\t\tСтрКоррК[ИмяКоррТЧ] = СчетКоррСсылка;',
    '\t\t\t\t\tУстановитьЕслиЕсть(СтрКоррК, "СуммаПлатежа", СуммаОперации);',
    '\t\t\t\t\tУстановитьЕслиЕсть(СтрКоррК, "Сумма", СуммаОперации);',
    '\t\t\t\t\tУстановитьЕслиЕсть(СтрКоррК, "СуммаВзаиморасчетов", СуммаОперации);',
    '\t\t\t\t\tУстановитьЕслиЕсть(СтрКоррК, "КурсВзаиморасчетов", 1);',
    '\t\t\t\t\tУстановитьЕслиЕсть(СтрКоррК, "КратностьВзаиморасчетов", 1);',
