    'Процедура ЗаполнитьКассуОрганизацииЕслиЕсть(ДокОбъект, Организация)',
    '\tЕсли ДокОбъект = Неопределено Тогда',
    '\t\tВозврат;',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tРеквКасса = ДокОбъект.Метаданные().Реквизиты.Найти("Касса");',
    '\t\tЕсли РеквКасса = Неопределено Или НЕ РеквКасса.Тип.СодержитТип(Тип("СправочникСсылка.Кассы")) Тогда',
    '\t\t\tВозврат;',
    '\t\tКонецЕсли;',
    '\t\tКассаСсылка = Неопределено;',
    '\t\tЕсли ЗначениеЗаполнено(Организация) Тогда',
    '\t\t\tПопытка',
    '\t\t\t\tЗапросКассаОрг = Новый Запрос;',
    '\t\t\t\tЗапросКассаОрг.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 Ссылка ИЗ Справочник.Кассы ГДЕ Владелец = &Организация И ПометкаУдаления = ЛОЖЬ";',
    '\t\t\t\tЗапросКассаОрг.УстановитьПараметр("Организация", Организация);',
    '\t\t\t\tТабКассаОрг = ЗапросКассаОрг.Выполнить().Выгрузить();',
    '\t\t\t\tЕсли ТабКассаОрг.Количество() > 0 Тогда',
    '\t\t\t\t\tКассаСсылка = ТабКассаОрг[0].Ссылка;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tИсключение',
    '\t\t\tКонецПопытки;',
    '\t\t\tЕсли НЕ ЗначениеЗаполнено(КассаСсылка) Тогда',
    '\t\t\t\tПопытка',
    '\t\t\t\t\tЗапросКассаОрг2 = Новый Запрос;',
