    '\t\t\t\tЗапросКассаВсе = Новый Запрос;',
    '\t\t\t\tЗапросКассаВсе.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 Ссылка ИЗ Справочник.Кассы ГДЕ ПометкаУдаления = ЛОЖЬ";',
    '\t\t\t\tТабКассаВсе = ЗапросКассаВсе.Выполнить().Выгрузить();',
