    'КонецПроцедуры',
    '',
    '&НаСервере',
    'Процедура ЗаполнитьБанковскиеСчетаШапкиПоМетаданным(Док, БанковскийСчетСсылка)',
    '\tЕсли Док = Неопределено Или НЕ ЗначениеЗаполнено(БанковскийСчетСсылка) Тогда',
    '\t\tВозврат;',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tТипБанкСчета = Тип("СправочникСсылка.БанковскиеСчета");',
    '\t\tСчРеквБС = 0;',
    '\t\tДля Каждого РеквБС Из Док.Метаданные().Реквизиты Цикл',
    '\t\t\tСчРеквБС = СчРеквБС + 1;',
    '\t\t\tЕсли СчРеквБС > 500 Тогда Прервать; КонецЕсли;',
