    '\t\t\tКонецЕсли;',
    '\t\t\tИмяРеквБСВРег = ВРег(Строка(РеквБС.Имя) + " " + Строка(РеквБС.Синоним));',
    '\t\t\tЕсли Найти(ИмяРеквБСВРег, "КОНТРАГЕНТ") > 0 Или Найти(ИмяРеквБСВРег, "ПЛАТЕЛЬЩИК") > 0 Или Найти(ИмяРеквБСВРег, "ПОЛУЧАТЕЛ") > 0 Тогда',
    '\t\t\t\tПродолжить;',
