    '\tКонецПопытки;',
    'КонецПроцедуры',
    '',
    '&НаСервере',
    'Процедура ПрименитьПогашениеЗадолженностиАвтоматически(Док)',
    '\tЕсли Док = Неопределено Тогда',
    '\t\tВозврат;',
    '\tКонецЕсли;',
    '\tЗначПогаш = НайтиПогашениеЗадолженностиАвтоматически(Док);',
    '\tЕсли НЕ ЗначениеЗаполнено(ЗначПогаш) Тогда',
    '\t\tВозврат;',
    '\tКонецЕсли;',
    '\tУстановитьЕслиЕсть(Док, "ПогашениеЗадолженности", ЗначПогаш);',
    '\tПопытка',
    '\t\tТЧРасшПЗ = Док.Метаданные().ТабличныеЧасти.Найти("РасшифровкаПлатежа");',
    '\t\tИмяКолПЗ = "ПогашениеЗадолженности";',
    '\t\tЕсли ТЧРасшПЗ <> Неопределено Тогда',
    '\t\t\tЕсли ТЧРасшПЗ.Реквизиты.Найти("ПогашениеЗадолженности") = Неопределено Тогда',
    '\t\t\t\tСчКолПЗ = 0;',
    '\t\t\t\tДля Каждого КандКолПЗ Из ТЧРасшПЗ.Реквизиты Цикл',
    '\t\t\t\t\tСчКолПЗ = СчКолПЗ + 1;',
    '\t\t\t\t\tЕсли СчКолПЗ > 200 Тогда Прервать; КонецЕсли;',
    '\t\t\t\t\tИмяКПЗ = СтрЗаменить(ВРег(Строка(КандКолПЗ.Имя) + " " + Строка(КандКолПЗ.Синоним)), " ", "");',
    '\t\t\t\t\tЕсли Найти(ИмяКПЗ, "ПОГАШЕНИЕЗАДОЛЖЕННОСТИ") > 0 Тогда',
    '\t\t\t\t\t\tИмяКолПЗ = КандКолПЗ.Имя;',
    '\t\t\t\t\t\tПрервать;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tКонецЦикла;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\t\tСчСтрПЗ = 0;',
    '\t\tДля Каждого СтрПЗ Из Док.РасшифровкаПлатежа Цикл',
    '\t\t\tСчСтрПЗ = СчСтрПЗ + 1;',
    '\t\t\tЕсли СчСтрПЗ > 200 Тогда Прервать; КонецЕсли;',
