    '\t\t\t// Ловим существующий СчетНаОплатуПокупателю с СуммаДокумента=0 или незаполненным Банковским счетом / Номенклатурой для перезаписи',
    '\t\t\tПопытка',
    '\t\t\t\tЗапрЧернСч = Новый Запрос;',
    '\t\t\t\tТекстЧернСч = "ВЫБРАТЬ ПЕРВЫЕ 5 Док.Ссылка КАК Ссылка, Док.Проведен КАК Проведен ИЗ Документ.СчетНаОплатуПокупателю КАК Док ГДЕ НЕ Док.ПометкаУдаления И Док.Дата МЕЖДУ &ДатаНач И &ДатаКон";',
    '\t\t\t\tЗапрЧернСч.УстановитьПараметр("ДатаНач", НачалоДня(ДатаДок));',
    '\t\t\t\tЗапрЧернСч.УстановитьПараметр("ДатаКон", КонецДня(ДатаДок));',
    '\t\t\t\tЕсли ЕстьРеквОрг И ЗначениеЗаполнено(ОргСсылка) Тогда',
    '\t\t\t\t\tТекстЧернСч = ТекстЧернСч + " И Док.Организация = &Организация";',
