    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tЗапросДвижДня = Новый Запрос;',
    '\t\tТекстДвижДня = "ВЫБРАТЬ ПЕРВЫЕ 500 Движ.Регистратор КАК Регистратор, Движ.СчетДт КАК СчетДт, Движ.СчетДт.Код КАК КодДт, Движ.СчетКт КАК СчетКт, Движ.СчетКт.Код КАК КодКт, Движ.Сумма КАК Сумма ИЗ РегистрБухгалтерии.Хозрасчетный КАК Движ ГДЕ Движ.Период МЕЖДУ &НачДня И &КонДня И Движ.Организация = &Организация И Движ.Активность = ИСТИНА";',
    '\t\tЕсли ЗначениеЗаполнено(ЧерновикИсключить) Тогда',
