    '\t\t\tЗапросДвижДня.УстановитьПараметр("ЧерновикИсключить", ЧерновикИсключить);',
    '\t\tКонецЕсли;',
    '\t\tЗапросДвижДня.Текст = ТекстДвижДня;',
    '\t\tЗапросДвижДня.УстановитьПараметр("НачДня", НачалоДня(ДатаДок));',
    '\t\tЗапросДвижДня.УстановитьПараметр("КонДня", КонецДня(ДатаДок));',
    '\t\tЗапросДвижДня.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\tТабДвижДня = ЗапросДвижДня.Выполнить().Выгрузить();',
    '\t\tЕсли ТабДвижДня.Количество() = 0 Тогда',
    '\t\t\tВозврат Неопределено;',
    '\t\tКонецЕсли;',
    '\t\tСчПровJSON = 0;',
    '\t\tДля Каждого ПровЭл Из МассивПроводокОп Цикл',
    '\t\t\tСчПровJSON = СчПровJSON + 1;',
    '\t\t\tЕсли СчПровJSON > 200 Тогда Прервать; КонецЕсли;',
    '\t\t\tКодДтЖ = СокрЛП(Строка(ПолучитьИзСоответствия(ПровЭл, "debit", "")));',
    '\t\t\tКодКтЖ = СокрЛП(Строка(ПолучитьИзСоответствия(ПровЭл, "credit", "")));',
    '\t\t\tСумЖ = Окр(Число(ПолучитьИзСоответствия(ПровЭл, "amount", 0)), 2);',
    '\t\t\tЕсли ПустаяСтрока(КодДтЖ) Или ПустаяСтрока(КодКтЖ) Или СумЖ <= 0 Тогда',
    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '\t\t\tСчДтЖСсылка = НайтиСчет(КодДтЖ);',
    '\t\t\tСчКтЖСсылка = НайтиСчет(КодКтЖ);',
    '\t\t\tСчСтрДвиж = 0;',
    '\t\t\tДля Каждого СтрДвиж Из ТабДвижДня Цикл',
    '\t\t\t\tСчСтрДвиж = СчСтрДвиж + 1;',
    '\t\t\t\tЕсли СчСтрДвиж > 500 Тогда Прервать; КонецЕсли;',
    '\t\t\t\tСумБД = Окр(Число(СтрДвиж.Сумма), 2);',
    '\t\t\t\tЕсли СумБД < (СумЖ - 1) Или СумБД > (СумЖ + 1) Тогда',
    '\t\t\t\t\tПродолжить;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tКодДтБД = СокрЛП(Строка(СтрДвиж.КодДт));',
    '\t\t\t\tКодКтБД = СокрЛП(Строка(СтрДвиж.КодКт));',
    '\t\t\t\tДтСовпал = (КодДтБД = КодДтЖ) Или (ЗначениеЗаполнено(СчДтЖСсылка) И СтрДвиж.СчетДт = СчДтЖСсылка);',
    '\t\t\t\tКтСовпал = (КодКтБД = КодКтЖ) Или (ЗначениеЗаполнено(СчКтЖСсылка) И СтрДвиж.СчетКт = СчКтЖСсылка);',
    '\t\t\t\tЕсли ДтСовпал И КтСовпал Тогда',
