    '\tКонецЕсли;',
    '\tИскСодержание = СокрЛП(Строка(ПолучитьИзСоответствия(ДокЭл, "comment", "")));',
    '\tПопытка',
    '\t\tЗапросЧернОп = Новый Запрос;',
    '\t\tЗапросЧернОп.Текст = "ВЫБРАТЬ ПЕРВЫЕ 20 Док.Ссылка КАК Ссылка, Док.Содержание КАК Содержание ИЗ Документ.ОперацияБух КАК Док ГДЕ НЕ Док.ПометкаУдаления И Док.Организация = &Организация И Док.Дата МЕЖДУ &НачДня И &КонДня УПОРЯДОЧИТЬ ПО Док.Дата";',
    '\t\tЗапросЧернОп.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\tЗапросЧернОп.УстановитьПараметр("НачДня", НачалоДня(ДатаДок));',
    '\t\tЗапросЧернОп.УстановитьПараметр("КонДня", КонецДня(ДатаДок));',
    '\t\tТабЧернОп = ЗапросЧернОп.Выполнить().Выгрузить();',
    '\t\tСчЧернОп = 0;',
    '\t\tДля Каждого СтрЧернОп Из ТабЧернОп Цикл',
    '\t\t\tСчЧернОп = СчЧернОп + 1;',
    '\t\t\tЕсли СчЧернОп > 50 Тогда Прервать; КонецЕсли;',
