    '',
    '&НаСервере',
    'Функция НайтиНативныйБанковскийСчетВладельца(Организация)',
    '\tЕсли НЕ ЗначениеЗаполнено(Организация) Тогда',
    '\t\tВозврат Неопределено;',
    '\tКонецЕсли;',
    '\tРезервныйИзДок = Неопределено;',
    '\t// Приоритет 1: счет организации из уже проведенных банковских документов в базе 1С (нативный счет Базы 0)',
    '\tПопытка',
    '\t\tЗапросБСИзДок = Новый Запрос;',
    '\t\tЗапросБСИзДок.Текст = "ВЫБРАТЬ ПЕРВЫЕ 10 Док.СчетОрганизации КАК СчетОрганизации, Док.СчетОрганизации.Наименование КАК Наименование, Док.СчетОрганизации.НомерСчета КАК НомерСчета, Док.Дата КАК Дата ИЗ Документ.СписаниеСРасчетногоСчета КАК Док ГДЕ Док.Организация = &Организация И Док.Проведен = ИСТИНА И НЕ Док.ПометкаУдаления И Док.СчетОрганизации <> ЗНАЧЕНИЕ(Справочник.БанковскиеСчета.ПустаяСсылка) И Док.СчетОрганизации.ПометкаУдаления = ЛОЖЬ ОБЪЕДИНИТЬ ВСЕ ВЫБРАТЬ ПЕРВЫЕ 10 ДокП.СчетОрганизации, ДокП.СчетОрганизации.Наименование, ДокП.СчетОрганизации.НомерСчета, ДокП.Дата ИЗ Документ.ПоступлениеНаРасчетныйСчет КАК ДокП ГДЕ ДокП.Организация = &Организация И ДокП.Проведен = ИСТИНА И НЕ ДокП.ПометкаУдаления И ДокП.СчетОрганизации <> ЗНАЧЕНИЕ(Справочник.БанковскиеСчета.ПустаяСсылка) И ДокП.СчетОрганизации.ПометкаУдаления = ЛОЖЬ УПОРЯДОЧИТЬ ПО Дата ВОЗР";',
    '\t\tЗапросБСИзДок.УстановитьПараметр("Организация", Организация);',
    '\t\tТабБСИзДок = ЗапросБСИзДок.Выполнить().Выгрузить();',
    '\t\tСчБСД = 0;',
    '\t\tДля Каждого СтрБСД Из ТабБСИзДок Цикл',
    '\t\t\tСчБСД = СчБСД + 1;',
    '\t\t\tЕсли СчБСД > 30 Тогда Прервать; КонецЕсли;',
