    '\t\t\tЕсли НЕ ЗначениеЗаполнено(РезервныйИзДок) Тогда',
    '\t\t\t\tРезервныйИзДок = СтрБСД.СчетОрганизации;',
    '\t\t\tКонецЕсли;',
    '\t\t\tНаимБСД = СокрЛП(ВРег(Строка(СтрБСД.Наименование)));',
    '\t\t\tНомБСД = СокрЛП(Строка(СтрБСД.НомерСчета));',
    '\t\t\tЭтоИскДок = (НаимБСД = "ОСНОВНОЙ РАСЧЕТНЫЙ СЧЕТ") Или (НомБСД = "40702810900000000001") Или (НомБСД = "40702810955000000001");',
    '\t\t\tЕсли НЕ ЭтоИскДок Тогда',
    '\t\t\t\tВозврат СтрБСД.СчетОрганизации;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЦикла;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\t// Приоритет 2: Организация.ОсновнойБанковскийСчет (если не пустой, не помечен на удаление и заполнен 20-значный НомерСчета)',
    '\tРезервныйОснОрг = Неопределено;',
    '\tПопытка',
    '\t\tОснСчетОрг = Организация.ОсновнойБанковскийСчет;',
    '\t\tЕсли ЗначениеЗаполнено(ОснСчетОрг) И НЕ ОснСчетОрг.ПометкаУдаления Тогда',
    '\t\t\tНомОсн = СокрЛП(Строка(ОснСчетОрг.НомерСчета));',
    '\t\t\tНаимОсн = СокрЛП(ВРег(Строка(ОснСчетОрг.Наименование)));',
    '\t\t\tЕсли СтрДлина(НомОсн) >= 20 Тогда',
    '\t\t\t\tЭтоИскОсн = (НаимОсн = "ОСНОВНОЙ РАСЧЕТНЫЙ СЧЕТ") Или (НомОсн = "40702810900000000001") Или (НомОсн = "40702810955000000001");',
    '\t\t\t\tЕсли НЕ ЭтоИскОсн Тогда',
