    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\t// Приоритет 3: существующий элемент Справочник.БанковскиеСчета организации (ПометкаУдаления = ЛОЖЬ) с 20-значным НомерСчета',
    '\tРезервный20Значный = Неопределено;',
