    '\t\t\tЕсли НЕ ЗначениеЗаполнено(РезервныйАктивныйСчет) Тогда',
    '\t\t\t\tРезервныйАктивныйСчет = СтрБСОрг.Ссылка;',
    '\t\t\tКонецЕсли;',
    '\t\t\tНомСтр = СокрЛП(Строка(СтрБСОрг.НомерСчета));',
    '\t\t\tНаимВРег = СокрЛП(ВРег(Строка(СтрБСОрг.Наименование)));',
    '\t\t\tЕсли СтрДлина(НомСтр) >= 20 Тогда',
    '\t\t\t\tЕсли НЕ ЗначениеЗаполнено(Резервный20Значный) Тогда',
    '\t\t\t\t\tРезервный20Значный = СтрБСОрг.Ссылка;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tЭтоИскусственный = (НаимВРег = "ОСНОВНОЙ РАСЧЕТНЫЙ СЧЕТ") Или (НомСтр = "40702810900000000001") Или (НомСтр = "40702810955000000001");',
    '\t\t\t\tЕсли НЕ ЭтоИскусственный Тогда',
    '\t\t\t\t\tВозврат СтрБСОрг.Ссылка;',
