    '\t\t\tКонецЕсли;',
    '\t\tКонецЦикла;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\tЕсли ЗначениеЗаполнено(РезервныйИзДок) Тогда Возврат РезервныйИзДок; КонецЕсли;',
