    '\tВозврат РезервныйАктивныйСчет;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция ПолучитьБанковскийСчетОрганизации(Организация)',
    '\tЕсли НЕ ЗначениеЗаполнено(Организация) Тогда',
    '\t\tВозврат Справочники.БанковскиеСчета.ПустаяСсылка();',
    '\tКонецЕсли;',
    '\tНайденНативныйБС = НайтиНативныйБанковскийСчетВладельца(Организация);',
    '\tЕсли ЗначениеЗаполнено(НайденНативныйБС) Тогда',
    '\t\tВалютаРубПров = ПолучитьВалютуРуб();',
    '\t\tЕсли ЗначениеЗаполнено(ВалютаРубПров) Тогда',
