    '\t\tКонецЕсли;',
    '\t\tВозврат НайденНативныйБС;',
    '\tКонецЕсли;',
    '\t// Приоритет 4: создаем новый счет ТОЛЬКО если у организации вообще 0 активных счетов в справочнике БанковскиеСчета',
    '\tПопытка',
    '\t\tЗапрНульБС = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 1 БС.Ссылка КАК Ссылка ИЗ Справочник.БанковскиеСчета КАК БС ГДЕ БС.Владелец = &Организация И БС.ПометкаУдаления = ЛОЖЬ");',
    '\t\tЗапрНульБС.УстановитьПараметр("Организация", Организация);',
