    '\tВозврат НайтиИлиСоздатьБанковскийСчет(Организация, "", "Основной банк организации", "");',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция НайтиИлиСоздатьБанковскийСчет(ВладелецСсылка, БИКБанка, ИмяБанка, НомерСчета)',
    '\tЧистыйНомер = СокрЛП(Строка(НомерСчета));',
    '\tЧистыйБИК = СокрЛП(Строка(БИКБанка));',
    '\tВалютаРуб = ПолучитьВалютуРуб();',
    '\tЕсли ЗначениеЗаполнено(ВладелецСсылка) Тогда',
    '\t\tПопытка',
    '\t\t\tЕсли ТипЗнч(ВладелецСсылка) = Тип("СправочникСсылка.Организации") Тогда',
    '\t\t\t\tСущСчетОрг = НайтиНативныйБанковскийСчетВладельца(ВладелецСсылка);',
    '\t\t\t\tЕсли ЗначениеЗаполнено(СущСчетОрг) Тогда',
    '\t\t\t\t\tВозврат СущСчетОрг;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tПопытка',
    '\t\t\tЗапросБС = Новый Запрос;',
    '\t\t\tЕсли НЕ ПустаяСтрока(ЧистыйНомер) Тогда',
    '\t\t\t\tЗапросБС.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 БС.Ссылка КАК Ссылка ИЗ Справочник.БанковскиеСчета КАК БС ГДЕ НЕ БС.ПометкаУдаления И БС.Владелец = &Владелец И БС.НомерСчета = &НомерСчета";',
    '\t\t\t\tЗапросБС.УстановитьПараметр("НомерСчета", ЧистыйНомер);',
    '\t\t\tИначе',
    '\t\t\t\tЗапросБС.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 БС.Ссылка КАК Ссылка ИЗ Справочник.БанковскиеСчета КАК БС ГДЕ НЕ БС.ПометкаУдаления И БС.Владелец = &Владелец";',
    '\t\t\tКонецЕсли;',
    '\t\t\tЗапросБС.УстановитьПараметр("Владелец", ВладелецСсылка);',
    '\t\t\tТабБС = ЗапросБС.Выполнить().Выгрузить();',
    '\t\t\tЕсли ТабБС.Количество() = 0 И НЕ ПустаяСтрока(ЧистыйНомер) Тогда',
    '\t\t\t\tЗапросБСЛюбой = Новый Запрос;',
    '\t\t\t\tЗапросБСЛюбой.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 БС.Ссылка КАК Ссылка ИЗ Справочник.БанковскиеСчета КАК БС ГДЕ НЕ БС.ПометкаУдаления И БС.Владелец = &Владелец";',
    '\t\t\t\tЗапросБСЛюбой.УстановитьПараметр("Владелец", ВладелецСсылка);',
    '\t\t\t\tТабБС = ЗапросБСЛюбой.Выполнить().Выгрузить();',
    '\t\t\tКонецЕсли;',
    '\t\t\tЕсли ТабБС.Количество() > 0 Тогда',
    '\t\t\t\tНайденБССсылка = ТабБС[0].Ссылка;',
    '\t\t\t\tЕсли ЗначениеЗаполнено(ВалютаРуб) Тогда',
    '\t\t\t\t\tПопытка',
    '\t\t\t\t\t\tЕсли НЕ ЗначениеЗаполнено(НайденБССсылка.ВалютаДенежныхСредств) Тогда',
    '\t\t\t\t\t\t\tОбБС = НайденБССсылка.ПолучитьОбъект();',
    '\t\t\t\t\t\t\tУстановитьЕслиЕсть(ОбБС, "ВалютаДенежныхСредств", ВалютаРуб);',
    '\t\t\t\t\t\t\tОбБС.Записать();',
    '\t\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tИсключение',
    '\t\t\t\t\tКонецПопытки;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tВозврат НайденБССсылка;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\tБанкСсылка = Неопределено;',
    '\tЕсли НЕ ПустаяСтрока(ЧистыйБИК) Тогда',
    '\t\tПопытка',
    '\t\t\tБанкСсылка = Справочники.КлассификаторБанков.НайтиПоКоду(ЧистыйБИК);',
    '\t\t\tЕсли НЕ ЗначениеЗаполнено(БанкСсылка) Тогда',
    '\t\t\t\tНовыйБанк = Справочники.КлассификаторБанков.СоздатьЭлемент();',
    '\t\t\t\tНовыйБанк.Код = ЧистыйБИК;',
    '\t\t\t\tНовыйБанк.Наименование = ?(ПустаяСтрока(ИмяБанка), "Банк БИК " + ЧистыйБИК, ИмяБанка);',
    '\t\t\t\tНовыйБанк.Записать();',
    '\t\t\t\tБанкСсылка = НовыйБанк.Ссылка;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\tПопытка',
    '\t\tНовыйСчет = Справочники.БанковскиеСчета.СоздатьЭлемент();',
    '\t\tНовыйСчет.Владелец = ВладелецСсылка;',
    '\t\tНовыйСчет.Наименование = "Основной расчетный счет";',
    '\t\tУстановитьЕслиЕсть(НовыйСчет, "НомерСчета", ?(ПустаяСтрока(ЧистыйНомер), "40702810900000000001", ЧистыйНомер));',
    '\t\tЕсли ЗначениеЗаполнено(БанкСсылка) Тогда',
    '\t\t\tУстановитьЕслиЕсть(НовыйСчет, "Банк", БанкСсылка);',
    '\t\tКонецЕсли;',
    '\t\tЕсли ЗначениеЗаполнено(ВалютаРуб) Тогда',
    '\t\t\tУстановитьЕслиЕсть(НовыйСчет, "ВалютаДенежныхСредств", ВалютаРуб);',
    '\t\tКонецЕсли;',
