    '\t\tВозврат НовыйСчет.Ссылка;',
    '\tИсключение',
    '\t\tВозврат Неопределено;',
    '\tКонецПопытки;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция НайтиИлиСоздатьОрганизацию(ДанныеОрг)',
    '\tИмяОрг = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеОрг, "name", "")));',
    '\tПолноеИмя = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеОрг, "fullName", ИмяОрг)));',
    '\tИННОрг = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеОрг, "inn", "")));',
    '\tКППОрг = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеОрг, "kpp", "")));',
    '\tБИКОрг = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеОрг, "bik", "044030653")));',
    '\tБанкОрг = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеОрг, "bankName", "СЕВЕРО-ЗАПАДНЫЙ БАНК ПАО СБЕРБАНК")));',
    '\tСчетОрг = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеОрг, "accountNumber", "")));',
    '',
    '\tОргСсылка = Неопределено;',
    '\tЕсли НЕ ПустаяСтрока(ИННОрг) Тогда',
    '\t\tПопытка',
    '\t\t\tЗапросОрг = Новый Запрос;',
    '\t\t\tЗапросОрг.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 Орг.Ссылка КАК Ссылка ИЗ Справочник.Организации КАК Орг ГДЕ НЕ Орг.ПометкаУдаления И Орг.ИНН = &ИНН";',
    '\t\t\tЗапросОрг.УстановитьПараметр("ИНН", ИННОрг);',
    '\t\t\tТабОргИНН = ЗапросОрг.Выполнить().Выгрузить();',
    '\t\t\tЕсли ТабОргИНН.Количество() > 0 Тогда',
    '\t\t\t\tОргСсылка = ТабОргИНН[0].Ссылка;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\tЕсли НЕ ЗначениеЗаполнено(ОргСсылка) И НЕ ПустаяСтрока(ИмяОрг) Тогда',
    '\t\tОргСсылка = Справочники.Организации.НайтиПоНаименованию(ИмяОрг);',
    '\tКонецЕсли;',
    '',
    '\tЕсли НЕ ЗначениеЗаполнено(ОргСсылка) И ПустаяСтрока(ИННОрг) Тогда',
    '\t\tПопытка',
    '\t\t\tЗапросЛюбойОрг = Новый Запрос;',
    '\t\t\tЗапросЛюбойОрг.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 Орг.Ссылка КАК Ссылка ИЗ Справочник.Организации КАК Орг ГДЕ НЕ Орг.ПометкаУдаления И НЕ Орг.ЭтоГруппа";',
    '\t\t\tТабЛюбойОрг = ЗапросЛюбойОрг.Выполнить().Выгрузить();',
    '\t\t\tЕсли ТабЛюбойОрг.Количество() > 0 Тогда',
    '\t\t\t\tОргСсылка = ТабЛюбойОрг[0].Ссылка;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\tЕсли НЕ ЗначениеЗаполнено(ОргСсылка) Тогда',
    '\t\tНоваяОрг = Справочники.Организации.СоздатьЭлемент();',
    '\t\tНоваяОрг.Наименование = ?(ПустаяСтрока(ИмяОрг), "ООО Организация", ИмяОрг);',
    '\t\tУстановитьЕслиЕсть(НоваяОрг, "НаименованиеСокращенное", НоваяОрг.Наименование);',
    '\t\tУстановитьЕслиЕсть(НоваяОрг, "НаименованиеПолное", ?(ПустаяСтрока(ПолноеИмя), НоваяОрг.Наименование, ПолноеИмя));',
    '\t\tУстановитьЕслиЕсть(НоваяОрг, "ИНН", ИННОрг);',
    '\t\tУстановитьЕслиЕсть(НоваяОрг, "КПП", КППОрг);',
    '\t\tПопытка',
    '\t\t\tУстановитьЕслиЕсть(НоваяОрг, "ЮридическоеФизическоеЛицо", Перечисления.ЮридическоеФизическоеЛицо.ЮридическоеЛицо);',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tНоваяОрг.Записать();',
    '\t\tОргСсылка = НоваяОрг.Ссылка;',
    '\tКонецЕсли;',
    '',
    '\tБанкСчетОрг = НайтиНативныйБанковскийСчетВладельца(ОргСсылка);',
    '\tЕсли НЕ ЗначениеЗаполнено(БанкСчетОрг) Тогда',
    '\t\tБанкСчетОрг = НайтиИлиСоздатьБанковскийСчет(ОргСсылка, БИКОрг, БанкОрг, СчетОрг);',
    '\tКонецЕсли;',
    '\tЕсли ЗначениеЗаполнено(БанкСчетОрг) Тогда',
    '\t\tПопытка',
    '\t\t\tТекОснБС = ОргСсылка.ОсновнойБанковскийСчет;',
    '\t\t\tНужноОбновитьОснБС = НЕ ЗначениеЗаполнено(ТекОснБС) Или ТекОснБС.ПометкаУдаления Или (СокрЛП(ВРег(Строка(ТекОснБС.Наименование))) = "ОСНОВНОЙ РАСЧЕТНЫЙ СЧЕТ" И ТекОснБС <> БанкСчетОрг);',
    '\t\t\tЕсли НужноОбновитьОснБС Тогда',
    '\t\t\t\tОргОбъект = ОргСсылка.ПолучитьОбъект();',
    '\t\t\t\tОргОбъект.ОсновнойБанковскийСчет = БанкСчетОрг;',
    '\t\t\t\tОргОбъект.Записать();',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\tВозврат ОргСсылка;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция НормализоватьИмяКонтрагентаДляПоиска(ИсходноеИмя)',
    '\tСтрНорм = НРег(СокрЛП(Строка(ИсходноеИмя)));',
    '\tЕсли ПустаяСтрока(СтрНорм) Тогда',
    '\t\tВозврат "";',
    '\tКонецЕсли;',
    '\tСтрНорм = СтрЗаменить(СтрНорм, "ё", "е");',
    '\tСтрНорм = СтрЗаменить(СтрНорм, Символы.НПП, " ");',
