    'Функция КлючСсылкиДляКэша(СсылкаОбъекта)',
    '\tЕсли НЕ ЗначениеЗаполнено(СсылкаОбъекта) Тогда',
    '\t\tВозврат "";',
    '\tКонецЕсли;',
