    '\tКонецЕсли;',
    '\tНайденПоСальдо = НайтиДоговорПоОстаткамНаДату(ОрганизацияСсылка, КонтрагентСсылка, ДатаДок, СчетаАвансовИДолга, СчетПриоритет1, ИскатьКт1, СчетПриоритет2, ИскатьКт2, НужныйВидПереч, ТекущийДогСсылка);',
    '\tЕсли НЕ ЗначениеЗаполнено(НайденПоСальдо) И НЕ СохранятьТекущийПриПерепроведении Тогда',
    '\t\tНайденПоСальдо = НайтиДоговорПоОстаткамНаДату(ОрганизацияСсылка, КонтрагентСсылка, КонецДня(ДатаДок) + 1, СчетаАвансовИДолга, СчетПриоритет1, ИскатьКт1, СчетПриоритет2, ИскатьКт2, НужныйВидПереч, ТекущийДогСсылка);',
    '\tКонецЕсли;',
    '\tЕсли ЗначениеЗаполнено(НайденПоСальдо) Тогда',
    '\t\tПроверитьВалютуДоговораКонтрагента(НайденПоСальдо, ВалютаРуб);',
    '\t\tВозврат НайденПоСальдо;',
    '\tКонецЕсли;',
    '\tЕсли СохранятьТекущийПриПерепроведении И ЗначениеЗаполнено(ТекущийДогСсылка) Тогда',
