    '\t\t\tЕсли НЕ ТекущийДогСсылка.ПометкаУдаления И ТекущийДогСсылка.Владелец = КонтрагентСсылка И ТекущийДогСсылка.ВидДоговора = НужныйВидПереч Тогда',
    '\t\t\t\tПроверитьВалютуДоговораКонтрагента(ТекущийДогСсылка, ВалютаРуб);',
    '\t\t\t\tВозврат ТекущийДогСсылка;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '\t// Если открытого сальдо нет — откатываемся к ОсновнойДоговорКонтрагента с нужным ВидДоговора',
