    '\t\tЕсли ЗначениеЗаполнено(ОснДогФолбэк) И НЕ ОснДогФолбэк.ПометкаУдаления И ОснДогФолбэк.Владелец = КонтрагентСсылка И ОснДогФолбэк.ВидДоговора = НужныйВидПереч Тогда',
    '\t\t\tПроверитьВалютуДоговораКонтрагента(ОснДогФолбэк, ВалютаРуб);',
