    '&НаСервере',
    'Функция НайтиИлиСоздатьСклад(ИмяСклада)',
    '\tЧистИмя = ?(ПустаяСтрока(СокрЛП(ИмяСклада)), "Основной склад", СокрЛП(ИмяСклада));',
    '\tНайден = Справочники.Склады.НайтиПоНаименованию(ЧистИмя);',
