    '&НаСервере',
    'Функция НайтиИлиСоздатьНоменклатуру(ДанныеНом)',
    '\tИмяНом = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеНом, "name", "")));',
    '\tЕсли ПустаяСтрока(ИмяНом) Тогда',
    '\t\tВозврат Справочники.Номенклатура.ПустаяСсылка();',
    '\tКонецЕсли;',
    '\tНайденНом = Справочники.Номенклатура.НайтиПоНаименованию(ИмяНом);',
    '\tЕсли ЗначениеЗаполнено(НайденНом) Тогда',
    '\t\tВозврат НайденНом;',
    '\tКонецЕсли;',
    '',
    '\tЭтоУслуга = Булево(ПолучитьИзСоответствия(ДанныеНом, "isService", Ложь));',
    '\tКодЕд = Строка(ПолучитьИзСоответствия(ДанныеНом, "unitCode", "796"));',
    '\tИмяЕд = Строка(ПолучитьИзСоответствия(ДанныеНом, "unitName", "шт"));',
    '\tСтавкаЧисло = Число(ПолучитьИзСоответствия(ДанныеНом, "vatRate", 20));',
    '\tВидНомИмя = Строка(ПолучитьИзСоответствия(ДанныеНом, "kind", "Материалы"));',
    '',
    '\tНоваяНом = Справочники.Номенклатура.СоздатьЭлемент();',
    '\tНоваяНом.Наименование = ИмяНом;',
    '\tУстановитьЕслиЕсть(НоваяНом, "НаименованиеПолное", ИмяНом);',
    '\tУстановитьЕслиЕсть(НоваяНом, "Услуга", ЭтоУслуга);',
    '\tЕдСсылка = НайтиИлиСоздатьЕдиницуИзмерения(КодЕд, ИмяЕд);',
    '\tЕсли ЗначениеЗаполнено(ЕдСсылка) Тогда',
    '\t\tУстановитьЕслиЕсть(НоваяНом, "ЕдиницаИзмерения", ЕдСсылка);',
    '\tКонецЕсли;',
    '\tСтавкаПереч = ПолучитьСтавкуНДСПеречисление(СтавкаЧисло, СтавкаЧисло <= 0);',
    '\tЕсли ЗначениеЗаполнено(СтавкаПереч) Тогда',
    '\t\tУстановитьЕслиЕсть(НоваяНом, "СтавкаНДС", СтавкаПереч);',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tВидНомСсылка = Справочники.ВидыНоменклатуры.НайтиПоНаименованию(ВидНомИмя);',
    '\t\tЕсли НЕ ЗначениеЗаполнено(ВидНомСсылка) Тогда',
    '\t\t\tНовыйВидНом = Справочники.ВидыНоменклатуры.СоздатьЭлемент();',
    '\t\t\tНовыйВидНом.Наименование = ВидНомИмя;',
    '\t\t\tУстановитьЕслиЕсть(НовыйВидНом, "Услуга", ЭтоУслуга);',
    '\t\t\tНовыйВидНом.Записать();',
    '\t\t\tВидНомСсылка = НовыйВидНом.Ссылка;',
    '\t\tКонецЕсли;',
    '\t\tУстановитьЕслиЕсть(НоваяНом, "ВидНоменклатуры", ВидНомСсылка);',
    '\tИсключение',
    '\tКонецПопытки;',
    '\tНоваяНом.Записать();',
    '\tВозврат НоваяНом.Ссылка;',
