    '&НаСервере',
    'Функция НайтиИлиСоздатьПодразделение(ОрганизацияСсылка, ИмяПодразделения = "Основное подразделение")',
    '\tПопытка',
    '\t\tНайденПодр = Справочники.ПодразделенияОрганизаций.НайтиПоНаименованию(ИмяПодразделения, Истина, , ОрганизацияСсылка);',
    '\t\tЕсли ЗначениеЗаполнено(НайденПодр) Тогда',
