    '&НаСервере',
    'Функция НайтиИлиСоздатьДолжность(ИмяДолжности)',
    '\tЧистДолж = ?(ПустаяСтрока(СокрЛП(ИмяДолжности)), "Специалист", СокрЛП(ИмяДолжности));',
    '\tПопытка',
