    '&НаСервере',
    'Функция НормализоватьФИОДляПоиска(ИсхФИО)',
    '\tСтрФ = НРег(СокрЛП(Строка(ИсхФИО)));',
    '\tЕсли ПустаяСтрока(СтрФ) Тогда',
    '\t\tВозврат "";',
    '\tКонецЕсли;',
    '\tСтрФ = СтрЗаменить(СтрФ, "ё", "е");',
    '\tСтрФ = СтрЗаменить(СтрФ, Символы.НПП, " ");',
    '\tСтрФ = СтрЗаменить(СтрФ, Символы.Таб, " ");',
    '\tСтрФ = СтрЗаменить(СтрФ, ".", " ");',
    '\tСтрФ = СтрЗаменить(СтрФ, ",", " ");',
    '\tДля СчПрФ = 1 По 6 Цикл',
    '\t\tСтрФ = СтрЗаменить(СтрФ, "  ", " ");',
    '\tКонецЦикла;',
    '\tВозврат СокрЛП(СтрФ);',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция РазбитьСтрокуПробеламиНаСлова(ИсхСтрока)',
    '\tМассСлов = Новый Массив;',
    '\tОстСтр = СокрЛП(Строка(ИсхСтрока));',
    '\tДля СчРазб = 1 По 12 Цикл',
    '\t\tЕсли ПустаяСтрока(ОстСтр) Тогда Прервать; КонецЕсли;',
    '\t\tПозПроб = Найти(ОстСтр, " ");',
    '\t\tЕсли ПозПроб = 0 Тогда',
    '\t\t\tМассСлов.Добавить(ОстСтр);',
    '\t\t\tПрервать;',
    '\t\tИначе',
    '\t\t\tСловоЧ = СокрЛП(Лев(ОстСтр, ПозПроб - 1));',
    '\t\t\tЕсли НЕ ПустаяСтрока(СловоЧ) Тогда',
    '\t\t\t\tМассСлов.Добавить(СловоЧ);',
    '\t\t\tКонецЕсли;',
    '\t\t\tОстСтр = СокрЛП(Сред(ОстСтр, ПозПроб + 1));',
    '\t\tКонецЕсли;',
    '\tКонецЦикла;',
    '\tВозврат МассСлов;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция ФИОСовпадаетСИнициалами(ФИОПервое, ФИОВторое)',
    '\tСл1 = РазбитьСтрокуПробеламиНаСлова(НормализоватьФИОДляПоиска(ФИОПервое));',
    '\tСл2 = РазбитьСтрокуПробеламиНаСлова(НормализоватьФИОДляПоиска(ФИОВторое));',
    '\tЕсли Сл1.Количество() < 2 Или Сл2.Количество() < 2 Тогда',
    '\t\tВозврат Ложь;',
    '\tКонецЕсли;',
    '\t// Фамилия обязана совпадать полностью (например, "федоров" = "федоров", а не "фадеев")',
    '\tЕсли Сл1[0] <> Сл2[0] Или СтрДлина(Сл1[0]) < 2 Тогда',
    '\t\tВозврат Ложь;',
    '\tКонецЕсли;',
    '\tИм1 = Сл1[1];',
    '\tИм2 = Сл2[1];',
    '\tЕсли Им1 <> Им2 И НЕ (СтрДлина(Им1) = 1 И Лев(Им2, 1) = Им1) И НЕ (СтрДлина(Им2) = 1 И Лев(Им1, 1) = Им2) Тогда',
    '\t\tВозврат Ложь;',
    '\tКонецЕсли;',
    '\tЕсли Сл1.Количество() >= 3 И Сл2.Количество() >= 3 Тогда',
    '\t\tОтч1 = Сл1[2];',
    '\t\tОтч2 = Сл2[2];',
    '\t\tЕсли Отч1 <> Отч2 И НЕ (СтрДлина(Отч1) = 1 И Лев(Отч2, 1) = Отч1) И НЕ (СтрДлина(Отч2) = 1 И Лев(Отч1, 1) = Отч2) Тогда',
    '\t\t\tВозврат Ложь;',
    '\t\tКонецЕсли;',
    '\tКонецЕсли;',
    '\tВозврат Истина;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция ЭтоЗаглушкаДолжностиВместоФИО(СтрПроверить)',
    '\tНормПров = НормализоватьФИОДляПоиска(СтрПроверить);',
    '\tЕсли ПустаяСтрока(НормПров) Тогда',
    '\t\tВозврат Истина;',
    '\tКонецЕсли;',
    '\tЕсли Найти(НормПров, "фио студент") > 0 Или Найти(НормПров, "сотрудник организац") > 0 Тогда',
    '\t\tВозврат Истина;',
    '\tКонецЕсли;',
    '\tЕсли НормПров = "главный бухгалтер" Или НормПров = "бухгалтер" Или НормПров = "генеральный директор" Или НормПров = "директор" Или НормПров = "руководитель" Или НормПров = "кассир" Или НормПров = "специалист" Или НормПров = "сотрудник" Или НормПров = "сотрудник штата" Или НормПров = "работник" Тогда',
    '\t\tВозврат Истина;',
    '\tКонецЕсли;',
    '\tВозврат Ложь;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция НайтиФИОГлавногоБухгалтераВБазе1С(ОрганизацияСсылка)',
    '\t// 1. РегистрСведений.ОтветственныеЛица (штатное хранение Главного бухгалтера в БП 3.0)',
    '\tПопытка',
    '\t\tЕсли Метаданные.РегистрыСведений.Найти("ОтветственныеЛица") <> Неопределено Тогда',
    '\t\t\tЗапросОтв = Новый Запрос;',
    '\t\t\tЗапросОтв.Текст = "ВЫБРАТЬ ПЕРВЫЕ 20 ПРЕДСТАВЛЕНИЕ(Отв.ОтветственноеЛицо) КАК Роль, Отв.ФизическоеЛицо.Наименование КАК ФИО ИЗ РегистрСведений.ОтветственныеЛица.СрезПоследних(, СтруктурнаяЕдиница = &Организация) КАК Отв";',
    '\t\t\tЗапросОтв.УстановитьПараметр("Организация", ОрганизацияСсылка);',
    '\t\t\tТабОтв = ЗапросОтв.Выполнить().Выгрузить();',
    '\t\t\tСчОтв = 0;',
    '\t\t\tДля Каждого СтрОтв Из ТабОтв Цикл',
    '\t\t\t\tСчОтв = СчОтв + 1;',
    '\t\t\t\tЕсли СчОтв > 30 Тогда Прервать; КонецЕсли;',
    '\t\t\t\tРольН = НРег(Строка(СтрОтв.Роль));',
    '\t\t\t\tКандФИО = СокрЛП(Строка(СтрОтв.ФИО));',
    '\t\t\t\tЕсли Найти(РольН, "бухгалтер") > 0 И НЕ ЭтоЗаглушкаДолжностиВместоФИО(КандФИО) Тогда',
    '\t\t\t\t\tВозврат КандФИО;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЦикла;',
    '\t\tКонецЕсли;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\t// 2. Карточка Справочник.Сотрудники, по которой еще не проведен ПриемНаРаботу (карточка студента в учебной БП 3.0)',
    '\tПопытка',
    '\t\tЗапросНепринят = Новый Запрос;',
    '\t\tЗапросНепринят.Текст = "ВЫБРАТЬ ПЕРВЫЕ 30 Сотр.Наименование КАК Наименование ИЗ Справочник.Сотрудники КАК Сотр ЛЕВОЕ СОЕДИНЕНИЕ Документ.ПриемНаРаботу КАК Пр ПО Пр.Сотрудник = Сотр.Ссылка И Пр.Проведен = ИСТИНА И НЕ Пр.ПометкаУдаления ГДЕ НЕ Сотр.ПометкаУдаления" + УсловиеБезГруппСправочника("Сотрудники", "Сотр") + " И Пр.Ссылка ЕСТЬ NULL УПОРЯДОЧИТЬ ПО Сотр.Код УБЫВ";',
    '\t\tТабНепринят = ЗапросНепринят.Выполнить().Выгрузить();',
    '\t\tСчНепр = 0;',
