    '&НаСервере',
    'Процедура ЗаполнитьФИОФизЛицаИРегистр(ФизЛицоСсылка, ФИО, ДатаАктуальности = Неопределено)',
    '\tЕсли НЕ ЗначениеЗаполнено(ФизЛицоСсылка) Или ПустаяСтрока(СокрЛП(ФИО)) Тогда',
    '\t\tВозврат;',
    '\tКонецЕсли;',
    '\tЧастиФИО = РазбитьСтрокуПробеламиНаСлова(ФИО);',
    '\tФамилияЧ = ?(ЧастиФИО.Количество() >= 1, ЧастиФИО[0], СокрЛП(ФИО));',
    '\tИмяЧ = ?(ЧастиФИО.Количество() >= 2, ЧастиФИО[1], "");',
    '\tОтчествоЧ = ?(ЧастиФИО.Количество() >= 3, ЧастиФИО[2], "");',
