    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tМДФЛ = Метаданные.Справочники.Найти("ФизическиеЛица");',
    '\t\tЕсли МДФЛ <> Неопределено Тогда',
    '\t\t\tНужнаЗаписьФЛ = Ложь;',
    '\t\t\tОбФЛФИО = ФизЛицоСсылка.ПолучитьОбъект();',
