    '\t\t\t\tНужнаЗаписьФЛ = Истина;',
    '\t\t\tКонецЕсли;',
    '\t\t\tЕсли МДФЛ.Реквизиты.Найти("ФИО") <> Неопределено И ПустаяСтрока(СокрЛП(Строка(ОбФЛФИО["ФИО"]))) Тогда',
    '\t\t\t\tОбФЛФИО["ФИО"] = ФИО;',
    '\t\t\t\tНужнаЗаписьФЛ = Истина;',
    '\t\t\tКонецЕсли;',
    '\t\t\tЕсли МДФЛ.Реквизиты.Найти("Фамилия") <> Неопределено И ПустаяСтрока(СокрЛП(Строка(ОбФЛФИО["Фамилия"]))) И НЕ ПустаяСтрока(ФамилияЧ) Тогда',
    '\t\t\t\tОбФЛФИО["Фамилия"] = ФамилияЧ;',
    '\t\t\t\tНужнаЗаписьФЛ = Истина;',
    '\t\t\tКонецЕсли;',
    '\t\t\tЕсли МДФЛ.Реквизиты.Найти("Имя") <> Неопределено И ПустаяСтрока(СокрЛП(Строка(ОбФЛФИО["Имя"]))) И НЕ ПустаяСтрока(ИмяЧ) Тогда',
    '\t\t\t\tОбФЛФИО["Имя"] = ИмяЧ;',
    '\t\t\t\tНужнаЗаписьФЛ = Истина;',
