    '\t\t\tЕсли МДФЛ.Реквизиты.Найти("Отчество") <> Неопределено И ПустаяСтрока(СокрЛП(Строка(ОбФЛФИО["Отчество"]))) И НЕ ПустаяСтрока(ОтчествоЧ) Тогда',
    '\t\t\t\tОбФЛФИО["Отчество"] = ОтчествоЧ;',
