    '\tКонецПопытки;',
    '\tПопытка',
    '\t\tМДРегФИО = Метаданные.РегистрыСведений.Найти("ФИОФизЛиц");',
    '\t\tЕсли МДРегФИО <> Неопределено И НЕ ПустаяСтрока(ФамилияЧ) Тогда',
    '\t\t\tИмяИзмФЛ = "ФизЛицо";',
    '\t\t\tЕсли МДРегФИО.Измерения.Найти("ФизическоеЛицо") <> Неопределено Тогда',
    '\t\t\t\tИмяИзмФЛ = "ФизическоеЛицо";',
    '\t\t\tИначеЕсли МДРегФИО.Измерения.Найти("ФизЛицо") <> Неопределено Тогда',
    '\t\t\t\tИмяИзмФЛ = "ФизЛицо";',
    '\t\t\tИначеЕсли МДРегФИО.Измерения.Количество() > 0 Тогда',
    '\t\t\t\tИмяИзмФЛ = МДРегФИО.Измерения[0].Имя;',
    '\t\t\tКонецЕсли;',
    '\t\t\tУжеЕстьЗаписьФИО = Ложь;',
    '\t\t\tПопытка',
    '\t\t\t\tЗапрПровФИО = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 1 Р.Фамилия КАК Фамилия ИЗ РегистрСведений.ФИОФизЛиц КАК Р ГДЕ Р." + ИмяИзмФЛ + " = &ФЛ");',
    '\t\t\t\tЗапрПровФИО.УстановитьПараметр("ФЛ", ФизЛицоСсылка);',
