    '\t\t\t\tЕсли ТабПровФИО.Количество() > 0 И НЕ ПустаяСтрока(СокрЛП(Строка(ТабПровФИО[0].Фамилия))) Тогда',
    '\t\t\t\t\tУжеЕстьЗаписьФИО = Истина;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tИсключение',
    '\t\t\tКонецПопытки;',
    '\t\t\tЕсли НЕ УжеЕстьЗаписьФИО Тогда',
