    '\t\t\t\tЕсли ГодАктуал < 2000 Тогда ГодАктуал = 2026; КонецЕсли;',
    '\t\t\t\tДатаНачГодаФИО = Дата(ГодАктуал, 1, 1, 0, 0, 0);',
    '\t\t\t\tДатаЗапаснаяФИО = ?(ЗначениеЗаполнено(ДатаАктуальности), НачалоДня(ДатаАктуальности), Дата(ГодАктуал, 4, 1, 0, 0, 0));',
    '\t\t\t\tЗаписаноФИОРег = Ложь;',
    '\t\t\t\tПопытка',
    '\t\t\t\t\tМенЗапФИО = РегистрыСведений.ФИОФизЛиц.СоздатьМенеджерЗаписи();',
    '\t\t\t\t\tУстановитьЕслиЕсть(МенЗапФИО, "Период", ДатаНачГодаФИО);',
    '\t\t\t\t\tМенЗапФИО[ИмяИзмФЛ] = ФизЛицоСсылка;',
    '\t\t\t\t\tУстановитьЕслиЕсть(МенЗапФИО, "Фамилия", ФамилияЧ);',
    '\t\t\t\t\tУстановитьЕслиЕсть(МенЗапФИО, "Имя", ИмяЧ);',
