    '&НаСервере',
    'Функция НайтиИлиСоздатьФизЛицоИСотрудника(ОрганизацияСсылка, ДанныеСотр)',
    '\tРезультат = Новый Структура("ФизЛицо, Сотрудник", Неопределено, Неопределено);',
    '\tФИО = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеСотр, "fio", "")));',
    '\tЕсли ПустаяСтрока(ФИО) Тогда',
    '\t\tФИО = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеСотр, "employeeName", "")));',
    '\tКонецЕсли;',
    '\tЕсли ПустаяСтрока(ФИО) Тогда',
    '\t\tФИО = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеСотр, "fullName", "")));',
    '\tКонецЕсли;',
    '\tЕсли ПустаяСтрока(ФИО) Тогда',
    '\t\tФИО = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеСотр, "name", "")));',
    '\tКонецЕсли;',
    '\tДолжКанд = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеСотр, "position", ПолучитьИзСоответствия(ДанныеСотр, "employeePosition", ""))));',
    '\tЕсли ЭтоЗаглушкаДолжностиВместоФИО(ФИО) Тогда',
    '\t\tЕсли Найти(НРег(ФИО + " " + ДолжКанд), "бухгалтер") > 0 Тогда',
    '\t\t\tФИО = НайтиФИОГлавногоБухгалтераВБазе1С(ОрганизацияСсылка);',
    '\t\tИначе',
    '\t\t\tФИО = "";',
    '\t\tКонецЕсли;',
    '\tКонецЕсли;',
    '\tЕсли ПустаяСтрока(ФИО) Или ЭтоЗаглушкаДолжностиВместоФИО(ФИО) Тогда',
