    '\tНормИскФИО = НормализоватьФИОДляПоиска(ФИО);',
    '\tДатаПриемаСтр = СокрЛП(Строка(ПолучитьИзСоответствия(ДанныеСотр, "hireDate", "")));',
    '\tДатаАктуалФИО = ?(НЕ ПустаяСтрока(ДатаПриемаСтр), РазобратьДатуISO(ДатаПриемаСтр, Ложь), Дата(2026, 4, 1, 0, 0, 0));',
    '\tСловаСозданияФИО = РазбитьСтрокуПробеламиНаСлова(ФИО);',
    '\tФамилияСозд = ?(СловаСозданияФИО.Количество() >= 1, СловаСозданияФИО[0], ФИО);',
    '\tИмяСозд = ?(СловаСозданияФИО.Количество() >= 2, СловаСозданияФИО[1], "");',
    '\tОтчествоСозд = ?(СловаСозданияФИО.Количество() >= 3, СловаСозданияФИО[2], "");',
    '',
    '\t// 1. Сначала ищем существующего Сотрудника в Справочники.Сотрудники (по точному и нормализованному ФИО)',
    '\tСотрудникСсылка = Справочники.Сотрудники.НайтиПоНаименованию(ФИО);',
    '\tЕсли НЕ ЗначениеЗаполнено(СотрудникСсылка) Тогда',
    '\t\tПопытка',
    '\t\t\tЗапросСотрПоиск = Новый Запрос;',
    '\t\t\tЗапросСотрПоиск.Текст = "ВЫБРАТЬ ПЕРВЫЕ 200 Сотр.Ссылка КАК Ссылка, Сотр.Наименование КАК Наименование ИЗ Справочник.Сотрудники КАК Сотр ГДЕ НЕ Сотр.ПометкаУдаления" + УсловиеБезГруппСправочника("Сотрудники", "Сотр") + " УПОРЯДОЧИТЬ ПО Сотр.Код";',
    '\t\t\tТабСотрПоиск = ЗапросСотрПоиск.Выполнить().Выгрузить();',
    '\t\t\tСчСП = 0;',
    '\t\t\tДля Каждого СтрСП Из ТабСотрПоиск Цикл',
    '\t\t\t\tСчСП = СчСП + 1;',
    '\t\t\t\tЕсли СчСП > 250 Тогда Прервать; КонецЕсли;',
    '\t\t\t\tЕсли НормализоватьФИОДляПоиска(СтрСП.Наименование) = НормИскФИО Тогда',
    '\t\t\t\t\tСотрудникСсылка = СтрСП.Ссылка;',
    '\t\t\t\t\tПрервать;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЦикла;',
    '\t\t\tЕсли НЕ ЗначениеЗаполнено(СотрудникСсылка) Тогда',
    '\t\t\t\tСчСП2 = 0;',
    '\t\t\t\tДля Каждого СтрСП2 Из ТабСотрПоиск Цикл',
