    '\t\t\tФизЛицоСсылка = Неопределено;',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\t// 2. Ищем существующее ФизическоеЛицо в Справочники.ФизическиеЛица (по точному, нормализованному и сокращенному с инициалами ФИО)',
    '\tЕсли НЕ ЗначениеЗаполнено(ФизЛицоСсылка) Тогда',
