    '\t\t\tЗапросФЛПоиск.Текст = "ВЫБРАТЬ ПЕРВЫЕ 200 ФЛ.Ссылка КАК Ссылка, ФЛ.Наименование КАК Наименование ИЗ Справочник.ФизическиеЛица КАК ФЛ ГДЕ НЕ ФЛ.ПометкаУдаления" + УсловиеБезГруппСправочника("ФизическиеЛица", "ФЛ") + " УПОРЯДОЧИТЬ ПО ФЛ.Код";',
    '\t\t\tТабФЛПоиск = ЗапросФЛПоиск.Выполнить().Выгрузить();',
    '\t\t\tСчФЛП = 0;',
    '\t\t\tДля Каждого СтрФЛП Из ТабФЛПоиск Цикл',
    '\t\t\t\tСчФЛП = СчФЛП + 1;',
    '\t\t\t\tЕсли СчФЛП > 250 Тогда Прервать; КонецЕсли;',
    '\t\t\t\tЕсли НормализоватьФИОДляПоиска(СтрФЛП.Наименование) = НормИскФИО Тогда',
    '\t\t\t\t\tФизЛицоСсылка = СтрФЛП.Ссылка;',
    '\t\t\t\t\tПрервать;',
    '\t\t\t\tКонецЕсли;',
