    '\t\t\t\t\t\tСчЗнВЗ = СчЗнВЗ + 1;',
    '\t\t\t\t\t\tЕсли СчЗнВЗ > 50 Тогда Прервать; КонецЕсли;',
    '\t\t\t\t\t\tЕсли ПервоеЗнВЗ = Неопределено Тогда',
    '\t\t\t\t\t\t\tПервоеЗнВЗ = МенеджерВЗ[ЗнВЗ.Имя];',
    '\t\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\t\tИмяВЗ = СтрЗаменить(ВРег(Строка(ЗнВЗ.Имя)), " ", "");',
    '\t\t\t\t\t\tСинВЗ = СтрЗаменить(ВРег(Строка(ЗнВЗ.Синоним)), " ", "");',
    '\t\t\t\t\t\tЕсли ИмяВЗ = "ОСНОВНОЕМЕСТОРАБОТЫ" Или СинВЗ = "ОСНОВНОЕМЕСТОРАБОТЫ" Или Найти(ИмяВЗ, "ОСНОВНОЕ") > 0 Или Найти(СинВЗ, "ОСНОВНОЕ") > 0 Тогда',
