    '\t\t\t\tПродолжить;',
    '\t\t\tКонецЕсли;',
    '\t\t\tПодходитРШ = (ИмяВШН = "НАЧИСЛЕНИЕ" Или ИмяВШН = "ОСНОВНОЕНАЧИСЛЕНИЕ" Или ИмяВШН = "ВИДРАСЧЕТА" Или ИмяВШН = "ВИДНАЧИСЛЕНИЯ" Или ИмяВШН = "ВИДОПЛАТЫ");',
