    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tИсключение',
    '\tКонецПопытки;',
    '\tЕсли ОписТиповНач = Неопределено Тогда',
    '\t\tОписТиповНач = ПолучитьОписаниеТиповНачисленияРегистраПН();',
    '\tКонецЕсли;',
    '',
    '\t// 1) Приоритет 1 (100% попадание в релиз): из существующих записей РегистрСведений.ПлановыеНачисления',
    '\tПопытка',
    '\t\tЗапрПН = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 1 Начисление ИЗ РегистрСведений.ПлановыеНачисления ГДЕ Начисление <> НЕОПРЕДЕЛЕНО УПОРЯДОЧИТЬ ПО Период УБЫВ");',
    '\t\tТабПН = ЗапрПН.Выполнить().Выгрузить();',
    '\t\tЕсли ТабПН.Количество() > 0 И ЗначениеЗаполнено(ТабПН[0][0]) Тогда',
