    '\tИсключение',
    '\tКонецПопытки;',
    '\t// Резерв для одиночного типа поля Начисление (где ГДЕ Начисление <> НЕОПРЕДЕЛЕНО вызывает ошибку несовместимых типов в запросе 1С 8.3)',
    '\tПопытка',
    '\t\tЗапрПН2 = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 30 Начисление КАК Начисление, ПРЕДСТАВЛЕНИЕ(Начисление) КАК Предст ИЗ РегистрСведений.ПлановыеНачисления УПОРЯДОЧИТЬ ПО Период УБЫВ");',
    '\t\tТабПН2 = ЗапрПН2.Выполнить().Выгрузить();',
