    '\t\tЗапрПНВР = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 30 ВидРасчета КАК Начисление, ПРЕДСТАВЛЕНИЕ(ВидРасчета) КАК Предст ИЗ РегистрСведений.ПлановыеНачисления УПОРЯДОЧИТЬ ПО Период УБЫВ");',
