    '\t\t\tЗапрДокШ = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 20 Док." + ИмяКолонкиНачисления + " КАК Начисление, ПРЕДСТАВЛЕНИЕ(Док." + ИмяКолонкиНачисления + ") КАК Предст ИЗ Документ.ПриемНаРаботу КАК Док ГДЕ Док.Проведен = ИСТИНА И НЕ Док.ПометкаУдаления УПОРЯДОЧИТЬ ПО Док.Дата УБЫВ");',
