    '\t\tЗапрНачЗП = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 20 ТЧ.Начисление КАК Начисление, ПРЕДСТАВЛЕНИЕ(ТЧ.Начисление) КАК Предст ИЗ Документ.НачислениеЗарплаты.Начисления КАК ТЧ ГДЕ ТЧ.Ссылка.Проведен = ИСТИНА И НЕ ТЧ.Ссылка.ПометкаУдаления УПОРЯДОЧИТЬ ПО ТЧ.Ссылка.Дата УБЫВ");',
    '\t\tТабНачЗП = ЗапрНачЗП.Выполнить().Выгрузить();',
