    '\t\t\t\t\t\tЗапрСпрН = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 5000 Эл.Ссылка КАК Ссылка, " + ПолеКодаЗапр + "ПРЕДСТАВЛЕНИЕ(Эл.Ссылка) КАК Наименование ИЗ Справочник." + ИмяМД + " КАК Эл ГДЕ НЕ Эл.ПометкаУдаления" + УслБезГрупп);',
    '\t\t\t\t\t\tТабСпрН = ЗапрСпрН.Выполнить().Выгрузить();',
