    '\t\t\t\t\t\t\tСчетчик = Счетчик + 1;',
    '\t\t\t\t\t\t\tЕсли Счетчик > 5000 Тогда Прервать; КонецЕсли;',
    '\t\t\t\t\t\t\tЕсли ЗначениеЗаполнено(СтрСпрН.Ссылка) Тогда',
    '\t\t\t\t\t\t\t\tЕсли ПервСпрН = Неопределено Тогда ПервСпрН = СтрСпрН.Ссылка; КонецЕсли;',
    '\t\t\t\t\t\t\t\tНаимВРегСпр = ВРег(СокрЛП(Строка(СтрСпрН.Наименование)));',
    '\t\t\t\t\t\t\t\tКодВРегСпр = ВРег(СокрЛП(Строка(СтрСпрН.Код)));',
    '\t\t\t\t\t\t\t\tЕсли Найти(НаимВРегСпр, "ОКЛАД") > 0 Или КодВРегСпр = "ОКЛ" Тогда',
    '\t\t\t\t\t\t\t\t\tВозврат СтрСпрН.Ссылка;',
    '\t\t\t\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\t\tКонецЦикла;',
    '\t\t\t\t\t\tЕсли ЗначениеЗаполнено(ПервСпрН) Тогда Возврат ПервСпрН; КонецЕсли;',
    '\t\t\t\t\tИсключение',
    '\t\t\t\t\tКонецПопытки;',
    '\t\t\t\t\tПопытка',
    '\t\t\t\t\t\tКандСпрКод = МенеджерСпрНач.НайтиПоКоду("ОКЛ");',
    '\t\t\t\t\t\tЕсли ЗначениеЗаполнено(КандСпрКод) Тогда Возврат КандСпрКод; КонецЕсли;',
