    '\t\t\t\t\tПопытка',
    '\t\t\t\t\t\tКандСпрНаим = МенеджерСпрНач.НайтиПоНаименованию("Оплата по окладу");',
    '\t\t\t\t\t\tЕсли ЗначениеЗаполнено(КандСпрНаим) Тогда Возврат КандСпрНаим; КонецЕсли;',
