    '\t\t\t\t\t\tНовСпрН.Наименование = "Оплата по окладу";',
    '\t\t\t\t\t\tЕсли ЕстьКодМД Тогда УстановитьЕслиЕсть(НовСпрН, "Код", "ОКЛ"); КонецЕсли;',
