    '\t\t\t\t\t\tПолеКонРБП = РеквРБП.Имя;',
    '\t\t\t\t\tИначеЕсли ПустаяСтрока(ПолеСпосРБП) И (ИмРБП = "СПОСОБСПИСАНИЯ" Или ИмРБП = "СПОСОБПРИЗНАНИЯРАСХОДОВ" Или ИмРБП = "ПОРЯДОКПРИЗНАНИЯРАСХОДОВ") Тогда',
    '\t\t\t\t\t\tПолеСпосРБП = РеквРБП.Имя;',
