    '\t\t\t\tКонецЦикла;',
    '\t\t\t\tЕстьСчетЗатрРБП = (МДРБП.Реквизиты.Найти("СчетЗатрат") <> Неопределено);',
    '\t\t\t\tТекстЗапрРБП = "ВЫБРАТЬ ПЕРВЫЕ 1000 Спр.Код КАК Код, Спр.Наименование КАК Наименование";',
    '\t\t\t\tТекстЗапрРБП = ТекстЗапрРБП + ?(ПустаяСтрока(ПолеСумРБП), ", 0 КАК Сумма", ", Спр." + ПолеСумРБП + " КАК Сумма");',
    '\t\t\t\tТекстЗапрРБП = ТекстЗапрРБП + ?(ПустаяСтрока(ПолеНачРБП), ", ДАТАВРЕМЯ(1, 1, 1) КАК ДатаНачалаСписания", ", Спр." + ПолеНачРБП + " КАК ДатаНачалаСписания");',
    '\t\t\t\tТекстЗапрРБП = ТекстЗапрРБП + ?(ПустаяСтрока(ПолеКонРБП), ", ДАТАВРЕМЯ(1, 1, 1) КАК ДатаОкончанияСписания", ", Спр." + ПолеКонРБП + " КАК ДатаОкончанияСписания");',
    '\t\t\t\tТекстЗапрРБП = ТекстЗапрРБП + ?(ПустаяСтрока(ПолеСпосРБП), ", """" КАК СпособСписания", ", ПРЕДСТАВЛЕНИЕ(Спр." + ПолеСпосРБП + ") КАК СпособСписания");',
    '\t\t\t\tТекстЗапрРБП = ТекстЗапрРБП + ?(ЕстьСчетЗатрРБП, ", Спр.СчетЗатрат.Код КАК СчетЗатрат", ", """" КАК СчетЗатрат");',
    '\t\t\t\tТекстЗапрРБП = ТекстЗапрРБП + " ИЗ Справочник.РасходыБудущихПериодов КАК Спр ГДЕ НЕ Спр.ПометкаУдаления" + УсловиеБезГруппСправочника("РасходыБудущихПериодов", "Спр");',
    '\t\t\t\tЗапрРБП = Новый Запрос(ТекстЗапрРБП);',
    '\t\t\t\tСчБ0РБП = 0;',
    '\t\t\t\tДля Каждого СтрРБПБ0 Из ЗапрРБП.Выполнить().Выгрузить() Цикл',
