    '\t\t\t\t\tЕсли ЗначениеЗаполнено(СтрРБПБ0.ДатаНачалаСписания) Тогда',
    '\t\t\t\t\t\tЗап.Вставить("ДатаНачалаСписания", Формат(СтрРБПБ0.ДатаНачалаСписания, "ДФ=гггг-ММ-дд"));',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tЕсли ЗначениеЗаполнено(СтрРБПБ0.ДатаОкончанияСписания) Тогда',
