    '',
    '\t\tМассивЦБ = Новый Массив;',
    '\t\tПопытка',
    '\t\t\tЕсли ЗначениеЗаполнено(ОргСсылка) Тогда',
    '\t\t\t\tЗапрЦБ = Новый Запрос("ВЫБРАТЬ ПЕРВЫЕ 200 ПРЕДСТАВЛЕНИЕ(Движ.СубконтоДт1) КАК Контрагент, ПРЕДСТАВЛЕНИЕ(Движ.СубконтоДт2) КАК Наименование, Движ.Сумма КАК Сумма, Движ.Период КАК Дата, Движ.Содержание КАК Содержание ИЗ РегистрБухгалтерии.Хозрасчетный КАК Движ ГДЕ Движ.Активность = ИСТИНА И Движ.Организация = &Организация И Движ.СчетДт.Код ПОДОБНО ""58.%"" УПОРЯДОЧИТЬ ПО Движ.Период ВОЗР");',
    '\t\t\t\tЗапрЦБ.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\t\t\tСчБ0ЦБ = 0;',
    '\t\t\t\tДля Каждого СтрЦБ Из ЗапрЦБ.Выполнить().Выгрузить() Цикл',
    '\t\t\t\t\tСчБ0ЦБ = СчБ0ЦБ + 1;',
