    '\t\t\t\t\tЗапЦБ.Вставить("Наименование", ?(ПустаяСтрока(СокрЛП(Строка(СтрЦБ.Наименование))), Строка(СтрЦБ.Контрагент), Строка(СтрЦБ.Наименование)));',
    '\t\t\t\t\tЗапЦБ.Вставить("Сумма", Число(СтрЦБ.Сумма));',
