    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tВсеСправочники.Вставить("ЦенныеБумаги", МассивЦБ);',
    '',
    '\t\t// 3. Начальные остатки Хозрасчетный: 1) на 01.01.<ОтчетныйГод>; 2) если 0 строк — на ПериодС с формы (если заполнен); 3) если 0 строк — на начало месяца после последнего проведенного документа базы',
    '\t\tДатаСрезаОстатков = ДатаНачалаГода;',
    '\t\tМассивОстатков = Новый Массив;',
    '\t\tЕсли ЗначениеЗаполнено(ОргСсылка) Тогда',
    '\t\t\tТекстЗапрОстБ0 = "ВЫБРАТЬ ПЕРВЫЕ 5000"',
    '\t\t\t\t+ " Ост.Счет.Код КАК Счет,"',
    '\t\t\t\t+ " Ост.Счет.Наименование КАК НаименованиеСчета,"',
    '\t\t\t\t+ " ПРЕДСТАВЛЕНИЕ(Ост.Субконто1) КАК Субконто1,"',
    '\t\t\t\t+ " Ост.СуммаОстатокДт КАК СальдоНачДт,"',
    '\t\t\t\t+ " Ост.СуммаОстатокКт КАК СальдоНачКт,"',
    '\t\t\t\t+ " Ост.КоличествоОстаток КАК КоличествоОстаток"',
    '\t\t\t\t+ " ИЗ РегистрБухгалтерии.Хозрасчетный.Остатки(&ДатаСрезаОстатков, , , Организация = &Организация) КАК Ост";',
    '\t\t\tПопытка',
    '\t\t\t\tЗапросОст = Новый Запрос(ТекстЗапрОстБ0);',
    '\t\t\t\tЗапросОст.УстановитьПараметр("ДатаСрезаОстатков", ДатаСрезаОстатков);',
    '\t\t\t\tЗапросОст.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\t\t\tСчБ0Ост = 0;',
    '\t\t\t\tДля Каждого СтрОст Из ЗапросОст.Выполнить().Выгрузить() Цикл',
    '\t\t\t\t\tСчБ0Ост = СчБ0Ост + 1;',
    '\t\t\t\t\tЕсли СчБ0Ост > 5000 Тогда Прервать; КонецЕсли;',
    '\t\t\t\t\tСтрокаОст = Новый Соответствие;',
