    '',
    '\t\t\t// Фолбэк 1: если на 01.01.<ОтчетныйГод> остатков 0 и на форме заполнен ПериодС (например, 01.04.2026), берем остатки на ПериодС',
    '\t\t\tЕсли МассивОстатков.Количество() = 0 Тогда',
