    '\t\t\t\t\t\t\tСтрокаОстП.Вставить("Субконто1", Строка(СтрОстП.Субконто1));',
    '\t\t\t\t\t\t\tСтрокаОстП.Вставить("СальдоНачДт", Число(СтрОстП.СальдоНачДт));',
