    '\t\t\t\t\t\t\tДобавитьСтрокуЛога("На 01.01." + Строка(ГодВыгрузки) + " остатков нет — взят срез начальных остатков на дату ПериодС: " + Формат(ДатаСрезаОстатков, "ДФ=дд.ММ.гггг"));',
