    '\t\t\tИначеЕсли Найти(ОбщВС, "склад") > 0 И ЗначениеЗаполнено(СкладСсылка) Тогда',
    '\t\t\t\tНаборСубконто[ТипВида] = СкладСсылка;',
    '\t\t\tИначеЕсли (Найти(ОбщВС, "работник") > 0 Или Найти(ОбщВС, "физ") > 0 Или Найти(ОбщВС, "сотрудник") > 0) И СотрСтруктура <> Неопределено Тогда',
    '\t\t\t\tЕсли ЗначениеЗаполнено(СотрСтруктура.ФизЛицо) Тогда',
