    '\t\tПКО.Записать(РежимЗаписиДокумента.Проведение);',
    '\t\tДобавитьСтрокуЛога("[АВТОПОПОЛНЕНИЕ КАССЫ 50.01 от " + Формат(ДатаПКО, "ДФ=дд.ММ.гггг") + "] Проведен парный ПКО (ПолучениеНаличныхВБанке, Дт 50.01 Кт 51) на " + Строка(НедостающаяСумма) + " руб.");',
    '\t\tВозврат ПКО.Ссылка;',
    '\tИсключение',
