    '\tСч6001 = НайтиСчет("60.01");',
    '\tСч6002 = НайтиСчет("60.02");',
    '\tСч6201 = НайтиСчет("62.01");',
    '\tСч6202 = НайтиСчет("62.02");',
    '\tСчетаРасчетов = Новый Массив;',
