    '\tЕсли ЗначениеЗаполнено(Сч6002) Тогда СчетаРасчетов.Добавить(Сч6002); КонецЕсли;',
    '\tЕсли ЗначениеЗаполнено(Сч6201) Тогда СчетаРасчетов.Добавить(Сч6201); КонецЕсли;',
    '\tЕсли ЗначениеЗаполнено(Сч6202) Тогда СчетаРасчетов.Добавить(Сч6202); КонецЕсли;',
