    '\t\t\t+ " Ост.Субконто1 КАК Контрагент,"',
    '\t\t\t+ " СУММА(ВЫБОР КОГДА Ост.Счет = &Сч6002 ТОГДА ЕСТЬNULL(Ост.СуммаОстатокДт, 0) ИНАЧЕ 0 КОНЕЦ) КАК Аванс6002,"',
    '\t\t\t+ " СУММА(ВЫБОР КОГДА Ост.Счет = &Сч6001 ТОГДА ЕСТЬNULL(Ост.СуммаОстатокКт, 0) ИНАЧЕ 0 КОНЕЦ) КАК Долг6001,"',
    '\t\t\t+ " СУММА(ВЫБОР КОГДА Ост.Счет = &Сч6202 ТОГДА ЕСТЬNULL(Ост.СуммаОстатокКт, 0) ИНАЧЕ 0 КОНЕЦ) КАК Аванс6202,"',
    '\t\t\t+ " СУММА(ВЫБОР КОГДА Ост.Счет = &Сч6201 ТОГДА ЕСТЬNULL(Ост.СуммаОстатокДт, 0) ИНАЧЕ 0 КОНЕЦ) КАК Долг6201"',
    '\t\t\t+ " ИЗ РегистрБухгалтерии.Хозрасчетный.Остатки(&ГраницаПроверки, Счет В (&СчетаРасчетов), , Организация = &Организация) КАК Ост"',
    '\t\t\t+ " СГРУППИРОВАТЬ ПО Ост.Субконто1";',
    '\t\tЗапросНезачт.УстановитьПараметр("ГраницаПроверки", ГраницаПроверки);',
