    '\t\tЗапросНезачт.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\tЗапросНезачт.УстановитьПараметр("Сч6001", Сч6001);',
    '\t\tЗапросНезачт.УстановитьПараметр("Сч6002", Сч6002);',
    '\t\tЗапросНезачт.УстановитьПараметр("Сч6201", Сч6201);',
    '\t\tЗапросНезачт.УстановитьПараметр("Сч6202", Сч6202);',
    '\t\tТабНезачт = ЗапросНезачт.Выполнить().Выгрузить();',
    '\t\tСчНЗ = 0;',
    '\t\tДля Каждого СтрНЗ Из ТабНезачт Цикл',
    '\t\t\tСчНЗ = СчНЗ + 1;',
    '\t\t\tЕсли СчНЗ > 300 Тогда Прервать; КонецЕсли;',
    '\t\t\tЕсли (Число(СтрНЗ.Аванс6002) > 0.01 И Число(СтрНЗ.Долг6001) > 0.01) Или (Число(СтрНЗ.Аванс6202) > 0.01 И Число(СтрНЗ.Долг6201) > 0.01) Тогда',
    '\t\t\t\tВозврат Истина;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЦикла;',
