    '&НаСервере',
    'Функция ПерепровестиПоступленияИРеализацииПериода(ОргСсылка, НачПериода, КонПериода, ВалютаРуб, КэшДоговоров)',
    '\tПерепроведеноШт = 0;',
    '\tЕсли НЕ ЗначениеЗаполнено(ОргСсылка) Тогда',
    '\t\tВозврат 0;',
    '\tКонецЕсли;',
    '\tПопытка',
    '\t\tЗапросХрон = Новый Запрос;',
    '\t\tТекстХрон = "ВЫБРАТЬ"',
    '\t\t\t+ " ДокПТУ.Ссылка КАК Ссылка,"',
    '\t\t\t+ " ДокПТУ.Дата КАК Дата,"',
    '\t\t\t+ " ""ПТУ"" КАК ВидКороткий"',
    '\t\t\t+ " ИЗ Документ.ПоступлениеТоваровУслуг КАК ДокПТУ"',
    '\t\t\t+ " ГДЕ НЕ ДокПТУ.ПометкаУдаления И ДокПТУ.Проведен = ИСТИНА И ДокПТУ.Организация = &Организация И ДокПТУ.Дата МЕЖДУ &НачПер И &КонПер"',
    '\t\t\t+ " ОБЪЕДИНИТЬ ВСЕ"',
    '\t\t\t+ " ВЫБРАТЬ"',
