    '\t\t\t\tПопытка ТекДогХрон = ОбХрон.ДоговорКонтрагента; Исключение КонецПопытки;',
    '\t\t\t\tЕсли ЗначениеЗаполнено(КонтрХрон) Тогда',
    '\t\t\t\t\tНужнВидХрон = ?(СтрХрон.ВидКороткий = "РТУ", "СПокупателем", "СПоставщиком");',
    '\t\t\t\t\tПодобрДог = ПодобратьДоговорПоЖивомуСальдоИлиОсновной(КонтрХрон, ОргСсылка, ОбХрон.Дата, ТекДогХрон, НужнВидХрон, СтрХрон.ВидКороткий, КэшДоговоров, ВалютаРуб, Истина);',
