    '\t\t\tИсключение',
    '\t\t\t\tДобавитьСтрокуЛога("Предупреждение автоперепроведения (" + Строка(СтрХрон.Ссылка) + "): " + СобратьТекстОшибки1С(ОписаниеОшибки()));',
    '\t\t\tКонецПопытки;',
    '\t\tКонецЦикла;',
    '\t\tЕсли ПерепроведеноШт > 0 Тогда',
    '\t\t\tДобавитьСтрокуЛога("[ХРОНОЛОГИЯ ЗАЧЕТА АВАНСОВ] Перепроведено в хронологическом порядке документов ПТУ/ДопРасходы/РТУ/ПередачаОС за период: " + Строка(ПерепроведеноШт));',
    '\t\tКонецЕсли;',
    '\tИсключение',
    '\t\tДобавитьСтрокуЛога("Предупреждение хронологического перепроведения периода: " + СобратьТекстОшибки1С(ОписаниеОшибки()));',
    '\tКонецПопытки;',
    '\tВозврат ПерепроведеноШт;',
    'КонецФункции',
    '',
    '&НаСервере',
    'Функция СоздатьУплатуНалоговПоЖивымОстаткам1С(ОргСсылка, ДокДанные, КонтрСсылка, ЧерновикСсылка = Неопределено)',
    '\tДатаДок = ПолучитьДатуВремяСлотаДокумента(РазобратьДатуISO(ПолучитьИзСоответствия(ДокДанные, "date", ""), Ложь), "СписаниеСРасчетногоСчета");',
    '\tДатаГраницы = НачалоДня(ДатаДок);',
    '\tШапка = ПолучитьИзСоответствия(ДокДанные, "header", Новый Соответствие);',
