    '\tТекстОперации = Строка(ПолучитьИзСоответствия(ДокДанные, "comment", "Уплата налогов и взносов"));',
    '\tСтатьяДДСИмя = Строка(ПолучитьИзСоответствия(Шапка, "cashFlowItem", "Уплата налогов и взносов"));',
    '\tВалютаРуб = ПолучитьВалютуРуб();',
    '\tБанкСчетОрг = ПолучитьБанковскийСчетОрганизации(ОргСсылка);',
    '\tСтатьяДДСНал = НайтиИлиСоздатьСтатьюДДС(СтатьяДДСИмя);',
    '',
    '\tСписокКУплате = Новый Массив;',
    '\tИсточникСумм = "живые остатки 1С на начало дня " + Формат(ДатаГраницы, "ДФ=дд.ММ.гггг") + " (Хозрасчетный.Остатки)";',
    '\tОшибкаЗапросаОстатковНал = Ложь;',
    '\tТекстОшибкиЗапросаНал = "";',
    '',
    '\t// 1. Формируем защищенный список существующих субсчетов 68.* и 69.* (отфильтровывая Неопределено, пустые ссылки и 68.04.2)',
    '\tСыройСписокСчетов = Новый Массив;',
    '\tКодыКандидатовНал = Новый Массив;',
    '\tКодыКандидатовНал.Добавить("68.01");',
    '\tКодыКандидатовНал.Добавить("68.01.1");',
    '\tКодыКандидатовНал.Добавить("68.01.2");',
    '\tКодыКандидатовНал.Добавить("68.02");',
    '\tКодыКандидатовНал.Добавить("68.03");',
    '\tКодыКандидатовНал.Добавить("68.04.1");',
    '\tКодыКандидатовНал.Добавить("68.06");',
    '\tКодыКандидатовНал.Добавить("68.07");',
    '\tКодыКандидатовНал.Добавить("68.08");',
    '\tКодыКандидатовНал.Добавить("68.10");',
    '\tКодыКандидатовНал.Добавить("68.12");',
    '\tКодыКандидатовНал.Добавить("68.9");',
    '\tКодыКандидатовНал.Добавить("68.90");',
    '\tКодыКандидатовНал.Добавить("69.01");',
    '\tКодыКандидатовНал.Добавить("69.02.1");',
    '\tКодыКандидатовНал.Добавить("69.02.2");',
    '\tКодыКандидатовНал.Добавить("69.02.7");',
    '\tКодыКандидатовНал.Добавить("69.03.1");',
    '\tКодыКандидатовНал.Добавить("69.03.2");',
    '\tКодыКандидатовНал.Добавить("69.09");',
    '\tКодыКандидатовНал.Добавить("69.11");',
    '\tДля Каждого ПровКанд Из МассивПроводок Цикл',
    '\t\tКодИзПров = СокрЛП(Строка(ПолучитьИзСоответствия(ПровКанд, "debit", "")));',
    '\t\tЕсли (Лев(КодИзПров, 2) = "68" Или Лев(КодИзПров, 2) = "69") И КодИзПров <> "68.04.2" И КодИзПров <> "68.04" Тогда',
    '\t\t\tКодыКандидатовНал.Добавить(КодИзПров);',
    '\t\tКонецЕсли;',
    '\tКонецЦикла;',
    '\tДля Каждого КодКанд Из КодыКандидатовНал Цикл',
    '\t\tСыройСписокСчетов.Добавить(НайтиСчет(КодКанд));',
    '\tКонецЦикла;',
    '\tПопытка',
    '\t\tЗапросВсех68_69 = Новый Запрос;',
    '\t\tЗапросВсех68_69.Текст = "ВЫБРАТЬ ПЕРВЫЕ 500 Сч.Ссылка КАК Ссылка, Сч.Код КАК Код ИЗ ПланСчетов.Хозрасчетный КАК Сч ГДЕ НЕ Сч.ПометкаУдаления И (Сч.Код ПОДОБНО ""68.%"" ИЛИ Сч.Код ПОДОБНО ""69.%"")";',
    '\t\tСчетчикСч68 = 0;',
    '\t\tДля Каждого СтрСчБД Из ЗапросВсех68_69.Выполнить().Выгрузить() Цикл',
    '\t\t\tСчетчикСч68 = СчетчикСч68 + 1;',
    '\t\t\tЕсли СчетчикСч68 > 5000 Тогда',
    '\t\t\t\tПрервать;',
    '\t\t\tКонецЕсли;',
    '\t\t\tКодБД = СокрЛП(Строка(СтрСчБД.Код));',
    '\t\t\tЕсли КодБД <> "68.04.2" И КодБД <> "68.04" Тогда',
    '\t\t\t\tСыройСписокСчетов.Добавить(СтрСчБД.Ссылка);',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЦикла;',
    '\tИсключение',
    '\tКонецПопытки;',
    '',
    '\tСписокСчетов = Новый Массив;',
    '\tДля Каждого КандСсылка Из СыройСписокСчетов Цикл',
    '\t\tЕсли КандСсылка <> Неопределено И ЗначениеЗаполнено(КандСсылка) Тогда',
    '\t\t\tЕсли СписокСчетов.Найти(КандСсылка) = Неопределено Тогда',
    '\t\t\t\tСписокСчетов.Добавить(КандСсылка);',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tКонецЦикла;',
    '',
    '\t// Запрос реального кредитового сальдо строго на НачалоДня(ДатаДок) (утро дня уплаты до документов текущего дня)',
    '\tЕсли ЗначениеЗаполнено(ОргСсылка) И СписокСчетов.Количество() > 0 Тогда',
    '\t\tПопытка',
    '\t\t\tЗапросНал = Новый Запрос;',
