    '\t\t\t\t+ " СУММА(ЕСТЬNULL(Ост.СуммаОстатокКт, 0)) КАК СуммаКт"',
    '\t\t\t\t+ " ИЗ РегистрБухгалтерии.Хозрасчетный.Остатки(&ДатаГраницы, Счет В (&СписокСчетов), , Организация = &Организация) КАК Ост"',
    '\t\t\t\t+ " СГРУППИРОВАТЬ ПО Ост.Счет, Ост.Счет.Код"',
    '\t\t\t\t+ " ИМЕЮЩИЕ СУММА(ЕСТЬNULL(Ост.СуммаОстатокКт, 0)) > 0"',
    '\t\t\t\t+ " УПОРЯДОЧИТЬ ПО КодСчета";',
    '\t\t\tЗапросНал.УстановитьПараметр("ДатаГраницы", ДатаГраницы);',
    '\t\t\tЗапросНал.УстановитьПараметр("СписокСчетов", СписокСчетов);',
    '\t\t\tЗапросНал.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\t\tСчетчикОстНал = 0;',
    '\t\t\tДля Каждого СтрНал Из ЗапросНал.Выполнить().Выгрузить() Цикл',
    '\t\t\t\tСчетчикОстНал = СчетчикОстНал + 1;',
    '\t\t\t\tЕсли СчетчикОстНал > 5000 Тогда',
    '\t\t\t\t\tПрервать;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tКодНалСтр = СокрЛП(Строка(СтрНал.КодСчета));',
    '\t\t\t\tЕсли КодНалСтр = "68.04.2" Или КодНалСтр = "68.04" Тогда',
    '\t\t\t\t\tПродолжить;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\t\tСуммаНалОст = Окр(Число(СтрНал.СуммаКт), 2);',
    '\t\t\t\tЕсли СуммаНалОст > 0 И СтрНал.СчетСсылка <> Неопределено И ЗначениеЗаполнено(СтрНал.СчетСсылка) Тогда',
    '\t\t\t\t\tЭлУпл = Новый Структура("СчетСсылка,КодСчета,Сумма", СтрНал.СчетСсылка, КодНалСтр, СуммаНалОст);',
    '\t\t\t\t\tСписокКУплате.Добавить(ЭлУпл);',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЦикла;',
    '\t\tИсключение',
    '\t\t\tОшибкаЗапросаОстатковНал = Истина;',
    '\t\t\tТекстОшибкиЗапросаНал = ОписаниеОшибки();',
    '\t\t\tДобавитьСтрокуЛога("ОШИБКА запроса живых остатков 68/69 на " + Формат(ДатаГраницы, "ДФ=дд.ММ.гггг") + ": " + ТекстОшибкиЗапросаНал);',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\t// 2. Быстрая проверка ОДНИМ запросом ПЕРВЫЕ 1: не проведена ли уже за эту дату уплата налогов/взносов (68.*, 69.*, 68.9 / 68.90)',
    '\tЕсли НЕ ОшибкаЗапросаОстатковНал И ЗначениеЗаполнено(ОргСсылка) И СписокСчетов.Количество() > 0 Тогда',
    '\t\tРегистраторУплатыСегодня = Неопределено;',
    '\t\tПопытка',
    '\t\t\tЗапросУплСегодня = Новый Запрос;',
    '\t\t\tЗапросУплСегодня.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 Движ.Регистратор КАК Регистратор ИЗ РегистрБухгалтерии.Хозрасчетный КАК Движ ГДЕ Движ.Активность И Движ.Организация = &Организация И Движ.Период МЕЖДУ &НачДня И &КонДня И Движ.СчетДт В (&СписокСчетов) И Движ.СчетКт = &Счет51";',
    '\t\t\tЗапросУплСегодня.УстановитьПараметр("НачДня", НачалоДня(ДатаДок));',
    '\t\t\tЗапросУплСегодня.УстановитьПараметр("КонДня", КонецДня(ДатаДок));',
    '\t\t\tЗапросУплСегодня.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\t\tЗапросУплСегодня.УстановитьПараметр("СписокСчетов", СписокСчетов);',
    '\t\t\tЗапросУплСегодня.УстановитьПараметр("Счет51", НайтиСчет("51"));',
    '\t\t\tТабУплСегодня = ЗапросУплСегодня.Выполнить().Выгрузить();',
    '\t\t\tЕсли ТабУплСегодня.Количество() > 0 Тогда',
    '\t\t\t\tРегистраторУплатыСегодня = ТабУплСегодня[0].Регистратор;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\t\tЕсли ЗначениеЗаполнено(РегистраторУплатыСегодня) Тогда',
    '\t\t\tЕсли СписокКУплате.Количество() = 0 Или ЭтотОбъект["ПропускатьСуществующиеРучныеДокументы"] Тогда',
    '\t\t\t\tДобавитьСтрокуЛога("[ПРОПУСК УПЛАТЫ НАЛОГОВ от " + Формат(ДатаДок, "ДФ=дд.ММ.гггг") + "] В базе за дату уже проведена уплата налогов/взносов (" + Строка(РегистраторУплатыСегодня) + ") — повторное списание не требуется.");',
    '\t\t\t\tВозврат 0;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tКонецЕсли;',
    '',
    '\t// 3. Фолбэк на суммы из пакета JSON, если живые остатки в 1С на начало дня равны нулю (и уплаты за день еще не было) или запрос не выполнился',
    '\tЕсли СписокКУплате.Количество() = 0 Тогда',
    '\t\tЕсли ОшибкаЗапросаОстатковНал Тогда',
    '\t\t\tИсточникСумм = "фолбэк из JSON (из-за ошибки запроса остатков 68/69: " + ТекстОшибкиЗапросаНал + ")";',
    '\t\tИначе',
    '\t\t\tИсточникСумм = "фолбэк из JSON (живые остатки 68/69 на начало дня " + Формат(ДатаГраницы, "ДФ=дд.ММ.гггг") + " равны 0)";',
    '\t\tКонецЕсли;',
    '\t\tНет6909ВБазе = НЕ ЗначениеЗаполнено(ПланыСчетов.Хозрасчетный.НайтиПоКоду("69.09"));',
    '\t\tДля Каждого ПровНал Из МассивПроводок Цикл',
    '\t\t\tКодДтН = СокрЛП(Строка(ПолучитьИзСоответствия(ПровНал, "debit", "")));',
    '\t\t\tСуммаПровН = Окр(Число(ПолучитьИзСоответствия(ПровНал, "amount", 0)), 2);',
    '\t\t\tЕсли СуммаПровН <= 0 Или (Лев(КодДтН, 2) <> "68" И Лев(КодДтН, 2) <> "69") Или КодДтН = "68.04.2" Тогда',
    '\t\t\t\tПродолжить;',
