    '\t\tЗапрПарт.Текст = "ВЫБРАТЬ ПЕРВЫЕ 1 ТЧТов.Ссылка КАК Ссылка, ТЧТов.Ссылка.Дата КАК Дата ИЗ Документ.ПоступлениеТоваровУслуг.Товары КАК ТЧТов ГДЕ ТЧТов.Ссылка.Организация = &Организация И ТЧТов.Ссылка.Проведен = ИСТИНА И НЕ ТЧТов.Ссылка.ПометкаУдаления И ТЧТов.Ссылка.Дата <= &КонДня И ТЧТов.Номенклатура = &Номенклатура ОБЪЕДИНИТЬ ВСЕ ВЫБРАТЬ ПЕРВЫЕ 1 ТЧОб.Ссылка, ТЧОб.Ссылка.Дата ИЗ Документ.ПоступлениеТоваровУслуг.Оборудование КАК ТЧОб ГДЕ ТЧОб.Ссылка.Организация = &Организация И ТЧОб.Ссылка.Проведен = ИСТИНА И НЕ ТЧОб.Ссылка.ПометкаУдаления И ТЧОб.Ссылка.Дата <= &КонДня И ТЧОб.Номенклатура = &Номенклатура УПОРЯДОЧИТЬ ПО Дата УБЫВ";',
