    '',
    '&НаСервере',
    'Процедура ЗаполнитьТЧАвансыАвансовогоОтчета(ДокОбъект, ОргСсылка, ФизЛицоСсылка, ДатаДок, СуммаОтчета, ВалютаРуб)',
    '\tЕсли ДокОбъект = Неопределено Или НЕ ЗначениеЗаполнено(ОргСсылка) Или НЕ ЗначениеЗаполнено(ФизЛицоСсылка) Тогда',
    '\t\tВозврат;',
