    'КонецПроцедуры',
    '',
    '&НаСервере',
    'Функция ПодобратьМатериалИСчет10ДляСписания(ОргСсылка, ДатаДок, ИсхНомСсылка, ИмяМатИзJSON, КодСчетаИзJSON, СуммаСтрИзJSON, КолСтрИзJSON, ТекстОперации)',
    '\tРезМат = Новый Структура("Номенклатура, СчетУчета, Количество", ИсхНомСсылка, Неопределено, ?(Число(КолСтрИзJSON) > 0, Число(КолСтрИзJSON), 1));',
    '\tЧистИмяМат = СокрЛП(Строка(ИмяМатИзJSON));',
    '\tЕсли НЕ ЗначениеЗаполнено(РезМат.Номенклатура) И НЕ ПустаяСтрока(ЧистИмяМат) Тогда',
    '\t\tПопытка',
    '\t\t\tНайденМатСпр = Справочники.Номенклатура.НайтиПоНаименованию(ЧистИмяМат);',
