    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\t// Приоритет 1 для СчетУчета и фолбэк для пустой/неизвестной Номенклатуры: фактические положительные остатки счетов 10.* на дату документа',
    '\tСчет10Гр = НайтиСчет("10");',
    '\tКолНаОстатке10 = 0;',
    '\tСуммаНаОстатке10 = 0;',
    '\tЕсли ЗначениеЗаполнено(ОргСсылка) И ЗначениеЗаполнено(Счет10Гр) Тогда',
    '\t\tПопытка',
    '\t\t\tЗапрОст10 = Новый Запрос;',
    '\t\t\tЗапрОст10.Текст = "ВЫБРАТЬ ПЕРВЫЕ 100 Ост.Субконто1 КАК Номенклатура, Ост.Счет КАК Счет, Ост.Счет.Код КАК КодСчета, ЕСТЬNULL(Ост.КоличествоОстатокДт, 0) КАК КолДт, ЕСТЬNULL(Ост.СуммаОстатокДт, 0) КАК СуммаДт ИЗ РегистрБухгалтерии.Хозрасчетный.Остатки(&ГраницаОст, Счет В ИЕРАРХИИ (&Счет10), , Организация = &Организация) КАК Ост ГДЕ (ЕСТЬNULL(Ост.СуммаОстатокДт, 0) > 0 ИЛИ ЕСТЬNULL(Ост.КоличествоОстатокДт, 0) > 0) УПОРЯДОЧИТЬ ПО СуммаДт УБЫВ";',
    '\t\t\tЗапрОст10.УстановитьПараметр("ГраницаОст", КонецДня(ДатаДок) + 1);',
    '\t\t\tЗапрОст10.УстановитьПараметр("Счет10", Счет10Гр);',
    '\t\t\tЗапрОст10.УстановитьПараметр("Организация", ОргСсылка);',
    '\t\t\tТабОст10 = ЗапрОст10.Выполнить().Выгрузить();',
    '\t\t\tЕсли ЗначениеЗаполнено(РезМат.Номенклатура) Тогда',
    '\t\t\t\tСчО10 = 0;',
    '\t\t\t\tДля Каждого СтрО10 Из ТабОст10 Цикл',
    '\t\t\t\t\tСчО10 = СчО10 + 1;',
    '\t\t\t\t\tЕсли СчО10 > 100 Тогда Прервать; КонецЕсли;',
    '\t\t\t\t\tКодСч10Канд = СокрЛП(Строка(СтрО10.КодСчета));',
    '\t\t\t\t\tЕсли Лев(КодСч10Канд, 5) = "10.11" Тогда Продолжить; КонецЕсли;',
    '\t\t\t\t\tЕсли СтрО10.Номенклатура = РезМат.Номенклатура И ЗначениеЗаполнено(СтрО10.Счет) Тогда',
    '\t\t\t\t\t\tРезМат.СчетУчета = СтрО10.Счет;',
    '\t\t\t\t\t\tКолНаОстатке10 = Число(СтрО10.КолДт);',
    '\t\t\t\t\t\tСуммаНаОстатке10 = Число(СтрО10.СуммаДт);',
    '\t\t\t\t\t\tПрервать;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tКонецЦикла;',
    '\t\t\tКонецЕсли;',
    '',
    '\t\t\t// Если Номенклатура пустая или по ней нет остатка на 10.*, подбираем подходящий материал с положительным остатком на 10.*',
    '\t\t\tЕсли НЕ ЗначениеЗаполнено(РезМат.Номенклатура) И ТабОст10.Количество() > 0 Тогда',
    '\t\t\t\tТекстПоискаН = НРег(ЧистИмяМат + " " + Строка(ТекстОперации));',
    '\t\t\t\tЛучшаяСтр10 = Неопределено;',
    '\t\t\t\tСчПодб10 = 0;',
    '\t\t\t\tДля Каждого СтрКанд10 Из ТабОст10 Цикл',
