    '\t\t\t\t\tКодСчКанд = СокрЛП(Строка(СтрКанд10.КодСчета));',
    '\t\t\t\t\tЕсли Лев(КодСчКанд, 5) = "10.11" Или НЕ ЗначениеЗаполнено(СтрКанд10.Номенклатура) Тогда Продолжить; КонецЕсли;',
    '\t\t\t\t\tИмНомКанд = НРег(СокрЛП(Строка(СтрКанд10.Номенклатура)));',
