    '\t\t\t\t\t\t\tЛучшаяСтр10 = СтрКанд10;',
    '\t\t\t\t\t\t\tПрервать;',
    '\t\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\t\tЕсли ЛучшаяСтр10 = Неопределено Тогда',
    '\t\t\t\t\t\tЛучшаяСтр10 = СтрКанд10;',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tКонецЦикла;',
    '\t\t\t\tЕсли ЛучшаяСтр10 <> Неопределено Тогда',
    '\t\t\t\t\tРезМат.Номенклатура = ЛучшаяСтр10.Номенклатура;',
    '\t\t\t\t\tРезМат.СчетУчета = ЛучшаяСтр10.Счет;',
    '\t\t\t\t\tКолНаОстатке10 = Число(ЛучшаяСтр10.КолДт);',
    '\t\t\t\t\tСуммаНаОстатке10 = Число(ЛучшаяСтр10.СуммаДт);',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЕсли;',
    '\t\tИсключение',
    '\t\tКонецПопытки;',
    '\tКонецЕсли;',
    '',
    '\t// Если остатков на 10.* нет вообще, создаем Номенклатуру по названию из JSON или описанию операции',
    '\tЕсли НЕ ЗначениеЗаполнено(РезМат.Номенклатура) Тогда',
    '\t\tИмяДляСоздМат = ЧистИмяМат;',
    '\t\tЕсли ПустаяСтрока(ИмяДляСоздМат) Тогда',
    '\t\t\tИмяДляСоздМат = СокрЛП(Лев(Строка(ТекстОперации), 80));',
    '\t\tКонецЕсли;',
    '\t\tЕсли ПустаяСтрока(ИмяДляСоздМат) Тогда',
    '\t\t\tИмяДляСоздМат = "Основные материалы";',
    '\t\tКонецЕсли;',
    '\t\tДанНовМат = Новый Соответствие;',
    '\t\tДанНовМат.Вставить("name", ИмяДляСоздМат);',
    '\t\tДанНовМат.Вставить("isService", Ложь);',
    '\t\tДанНовМат.Вставить("kind", "Материалы");',
    '\t\tДанНовМат.Вставить("unitCode", "796");',
    '\t\tДанНовМат.Вставить("unitName", "шт");',
    '\t\tДанНовМат.Вставить("vatRate", 20);',
    '\t\tРезМат.Номенклатура = НайтиИлиСоздатьНоменклатуру(ДанНовМат);',
    '\tКонецЕсли;',
    '',
    '\t// Приоритет 2 и 3 для СчетУчета: счет из JSON (субсчет 10.*) -> фолбэк 10.01',
    '\tЕсли НЕ ЗначениеЗаполнено(РезМат.СчетУчета) Тогда',
    '\t\tЧистКодСч = СокрЛП(Строка(КодСчетаИзJSON));',
    '\t\tЕсли НЕ ПустаяСтрока(ЧистКодСч) И ЧистКодСч <> "10" Тогда',
