    '\t\t\tЕсли ЗначениеЗаполнено(СчИзJSON) Тогда',
    '\t\t\t\tРезМат.СчетУчета = СчИзJSON;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tКонецЕсли;',
    '\tЕсли НЕ ЗначениеЗаполнено(РезМат.СчетУчета) Тогда',
    '\t\tРезМат.СчетУчета = НайтиСчет("10.01");',
    '\tКонецЕсли;',
    '',
    '\t// Выверка количества по фактическому остатку 10.* (чтобы не превышать остаток и полностью закрывать партию при полном списании)',
    '\tЕсли КолНаОстатке10 > 0 Тогда',
    '\t\tЕсли РезМат.Количество > КолНаОстатке10 Тогда',
