    '\t\tКонецЕсли;',
    '\tИсключение',
    '\tКонецПопытки;',
    '',
    '\t// Запись или проведение нативного документа (при ошибке проведения сохраняем сам заполненный ДокОбъект как черновик и возвращаем дамп полей)',
