    '\tИсключение',
    '\t\tПервичнаяОшЗап = СобратьТекстОшибки1С(ОписаниеОшибки());',
    '\t\tДампПриОшибке = СформироватьДампПолейДокумента(ДокОбъект);',
    '\t\tЕсли НЕ ПустаяСтрока(ДиагностикаТипаНачисленияПриема) Тогда',
    '\t\t\tДампПриОшибке = ДампПриОшибке + "; " + ДиагностикаТипаНачисленияПриема;',
