    '',
    '&НаСервере',
    'Процедура ПодготовитьСправочникиДляДокументаПакета(ДокЭл, ОргСсылка, ВалютаРубПакет, СырыеКонтрПакета, СырыеДогПакета, СырыеНомПакета, СырыеСотрПакета, СырыеОСПакета, СырыеРБППакета, КартаКонтр, КартаДог, КартаНом, КартаСотр, КартаОС, КартаРБП, КэшКонтрПоИНН, КэшКонтрПоНормИмени, КэшДоговоров)',
    '\tШапкаП = ПолучитьИзСоответствия(ДокЭл, "header", Новый Соответствие);',
    '\tСтрокиП = ПолучитьИзСоответствия(ДокЭл, "rows", Новый Массив);',
