    '\t\tСырК = ПолучитьИзСоответствия(СырыеКонтрПакета, КлючКП, Неопределено);',
    '\t\tЕсли СырК <> Неопределено Тогда',
    '\t\t\tСсылкаК = НайтиИлиСоздатьКонтрагента(СырК, КэшКонтрПоИНН, КэшКонтрПоНормИмени);',
    '\t\t\tЕсли ЗначениеЗаполнено(СсылкаК) Тогда',
    '\t\t\t\tКартаКонтр.Вставить(КлючКП, СсылкаК);',
