    '\t\tКонецЕсли;',
    '\tКонецЕсли;',
    '',
    '\tКлючДП = Строка(ПолучитьИзСоответствия(ШапкаП, "contractKey", ""));',
    '\tЕсли НЕ ПустаяСтрока(КлючДП) И ПолучитьИзСоответствия(КартаДог, КлючДП, Неопределено) = Неопределено Тогда',
