    '\t\t\t\tЕсли СырВлад <> Неопределено Тогда',
    '\t\t\t\t\tВладСсылкаП = НайтиИлиСоздатьКонтрагента(СырВлад, КэшКонтрПоИНН, КэшКонтрПоНормИмени);',
    '\t\t\t\t\tЕсли ЗначениеЗаполнено(ВладСсылкаП) Тогда',
    '\t\t\t\t\t\tКартаКонтр.Вставить(ВладКлючП, ВладСсылкаП);',
    '\t\t\t\t\tКонецЕсли;',
    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЕсли;',
    '\t\t\tЕсли ЗначениеЗаполнено(ВладСсылкаП) Тогда',
    '\t\t\t\tСсылкаД = НайтиИлиСоздатьДоговор(ВладСсылкаП, ОргСсылка, СырД, КэшДоговоров, ВалютаРубПакет);',
    '\t\t\t\tЕсли ЗначениеЗаполнено(СсылкаД) Тогда',
