    '\t\t\t\tКонецЕсли;',
    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\tКонецЕсли;',
    '',
    '\tКлючСП = Строка(ПолучитьИзСоответствия(ШапкаП, "employeeKey", ""));',
    '\tЕсли НЕ ПустаяСтрока(КлючСП) И ПолучитьИзСоответствия(КартаСотр, КлючСП, Неопределено) = Неопределено Тогда',
    '\t\tСырС = ПолучитьИзСоответствия(СырыеСотрПакета, КлючСП, Неопределено);',
    '\t\tЕсли СырС <> Неопределено Тогда',
    '\t\t\tПараС = НайтиИлиСоздатьФизЛицоИСотрудника(ОргСсылка, СырС);',
