    '\t\tКонецЕсли;',
    '\t\tКлючНомП = Строка(ПолучитьИзСоответствия(СтрП, "nomenclatureKey", ""));',
    '\t\tЕсли НЕ ПустаяСтрока(КлючНомП) И ПолучитьИзСоответствия(КартаНом, КлючНомП, Неопределено) = Неопределено Тогда',
