    '\t\t\t\tСсылкаН = НайтиИлиСоздатьНоменклатуру(СырН);',
    '\t\t\t\tЕсли ЗначениеЗаполнено(СсылкаН) Тогда',
    '\t\t\t\t\tКартаНом.Вставить(КлючНомП, СсылкаН);',
