    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\t\tКлючСотрСтрП = Строка(ПолучитьИзСоответствия(СтрП, "employeeKey", ""));',
    '\t\tЕсли НЕ ПустаяСтрока(КлючСотрСтрП) И ПолучитьИзСоответствия(КартаСотр, КлючСотрСтрП, Неопределено) = Неопределено Тогда',
    '\t\t\tСырССтр = ПолучитьИзСоответствия(СырыеСотрПакета, КлючСотрСтрП, Неопределено);',
