    '\t\t\t\tПараССтр = НайтиИлиСоздатьФизЛицоИСотрудника(ОргСсылка, СырССтр);',
    '\t\t\t\tЕсли ПараССтр <> Неопределено Тогда',
    '\t\t\t\t\tКартаСотр.Вставить(КлючСотрСтрП, ПараССтр);',
