    '\t\t\tКонецЕсли;',
    '\t\tКонецЕсли;',
    '\t\tКлючОСП = Строка(ПолучитьИзСоответствия(СтрП, "fixedAssetKey", ""));',
    '\t\tЕсли НЕ ПустаяСтрока(КлючОСП) И ПолучитьИзСоответствия(КартаОС, КлючОСП, Неопределено) = Неопределено Тогда',
    '\t\t\tСырОС = ПолучитьИзСоответствия(СырыеОСПакета, КлючОСП, Неопределено);',
    '\t\t\tЕсли СырОС <> Неопределено Тогда',
    '\t\t\t\tСсылкаОС = НайтиИлиСоздатьОС(СырОС);',
    '\t\t\t\tЕсли ЗначениеЗаполнено(СсылкаОС) Тогда',
    '\t\t\t\t\tКартаОС.Вставить(КлючОСП, СсылкаОС);',
