    '\t\t\tСотрД = ПолучитьИзСоответствия(КартаСотр, Строка(ПолучитьИзСоответствия(ШапкаД, "employeeKey", "")), Неопределено);',
    '\t\t\tЕсли (ВидМетаРеальный = "ПриемНаРаботу" Или ВидМетаРеальный = "КадровыйПеревод" Или ВидМетаРеальный = "ИсполнительныйЛист" Или ВидМетаРеальный = "Увольнение" Или ВидМетаРеальный = "УвольнениеИзОрганизации" Или ВидМетаРеальный = "АвансовыйОтчет") И (СотрД = Неопределено Или НЕ ЗначениеЗаполнено(СотрД.Сотрудник)) Тогда',
