    '\t\t\t\t\t\tЕсли РежимДинОстатка = "payroll_balance" Или Лев(КодДтПроп, 2) = "70" Или ВидОпПроп = "ВыплатаЗаработнойПлатыПоВедомостям" Или ВидОпПроп = "ВыплатаЗаработнойПлатыРаботнику" Или ДокументСодержитСнятиеНаличныхИзБанка51(ДокЭл) Тогда',
