    '\t\t\t\t\tНайденныйРучнойДок = НайтиСуществующийРучнойДубльДокумента(ВидМетаРеальный, ОргСсылка, ДатаДокПроверка, КонтрД, СуммаДляСверкиДубля, СотрД);',
    '\t\t\t\t\tЕсли ЗначениеЗаполнено(НайденныйРучнойДок) Тогда',
