    '\t\t\t\t\tКолПлатежекНал = СоздатьУплатуНалоговПоЖивымОстаткам1С(ОргСсылка, ДокЭл, КонтрД, ЧерновикДляПерезаписи);',
    '\t\t\t\t\tЕсли КолПлатежекНал = 0 Тогда',
